92	// StatePublisher is invoked from Process whenever the observable state of
93	// the process changes. It is supplied by the owner (typically ProjectRunner)
94	// and may be nil — Process treats that as a no-op.
95	type StatePublisher func(ev types.ProcessStateEvent)
96	
97	// waitResult reports how a wait on another process ended.
98	type waitResult int
99	
100	const (
101		// waitOk - the awaited condition was met.
102		waitOk waitResult = iota
103		// waitFailed - the awaited process terminated without meeting the condition.
104		waitFailed
105		// waitAborted - the *waiting* process was shut down before the condition
106		// was met, so it must not run at all.
107		waitAborted
108	)
