273	func (p *Process) getProcessStarter() func() error {
274		return func() error {
275			p.command = p.getCommander()
276			p.command.SetEnv(p.getProcessEnvironment())
277			p.command.SetDir(p.procConf.WorkingDir)
278	
279			if p.isMain || (p.procConf.IsElevated && !p.isTuiEnabled) {
280				p.command.AttachIo()
281			} else {
282				p.command.SetCmdArgs()
283				if p.truncateLogs {
284					p.logBuffer.Truncate()
285				}
286				if !p.procConf.IsInteractive {
287					stdout, _ := p.command.StdoutPipe()
288					p.stdOutDone = make(chan struct{})
289					go p.handleOutput(stdout, "stdout", p.handleInfo, p.stdOutDone)
290				}
291				if !p.procConf.IsTty && !p.procConf.IsInteractive {
292					stderr, _ := p.command.StderrPipe()
293					p.stdErrDone = make(chan struct{})
294					go p.handleOutput(stderr, "stderr", p.handleError, p.stdErrDone)
295				}
296			}
297	
298			if p.procConf.IsElevated && p.isTuiEnabled {
299				stdin, err := p.command.StdinPipe()
300				if err != nil {
301					log.Error().Err(err).Msg("Failed to get stdin pipe")
302				}
303				p.stdin = stdin
304			}
305	
306			return p.command.Start()
307		}
308	}
