310	func (p *Process) getCommander() command.Commander {
311		if (p.procConf.IsTty || p.procConf.IsInteractive) && !p.isMain {
312			return command.BuildPtyCommand(
313				p.procConf.Executable,
314				p.mergeExtraArgs(),
315			)
316		} else {
317			return command.BuildCommand(
318				p.procConf.Executable,
319				p.mergeExtraArgs(),
320			)
321		}
322	
323	}
324	
325	func (p *Process) mergeExtraArgs() []string {
326		if len(p.extraArgs) == 0 {
327			return p.procConf.Args
328		}
329		tmp := make([]string, len(p.procConf.Args))
330		copy(tmp, p.procConf.Args)
331		if isStringDefined(p.procConf.Command) {
332			lastArg := p.procConf.Args[len(p.procConf.Args)-1]
333			lastArg += " " + strings.Join(p.extraArgs, " ")
334			return append(tmp[:len(tmp)-1], lastArg)
335		} else if len(p.procConf.Entrypoint) > 0 {
336			return append(tmp, p.extraArgs...)
337		}
338		return p.procConf.Args
339	}
