341	func (p *Process) getBackoff() time.Duration {
342		backoff := max(p.procConf.RestartPolicy.BackoffSeconds, 1)
343		return time.Duration(backoff) * time.Second
344	}
345	
346	func (p *Process) getProcessEnvironment() []string {
347		return buildProcessEnvironment(p.procConf, p.globalEnv, p.dotEnvVars)
348	}
