350	func (p *Process) isRestartable() bool {
351		p.Lock()
352		exitCode := p.getExitCode()
353		p.Unlock()
354		if p.isStopped.Swap(false) {
355			return false
356		}
357		if p.procConf.RestartPolicy.Restart == types.RestartPolicyNo {
358			return false
359		}
360	
361		if !p.procConf.IsExitCodeSuccess(exitCode) && p.procConf.RestartPolicy.Restart == types.RestartPolicyExitOnFailure {
362			return false
363		}
364	
365		if !p.procConf.IsExitCodeSuccess(exitCode) && p.procConf.RestartPolicy.Restart == types.RestartPolicyOnFailure {
366			if p.procConf.RestartPolicy.MaxRestarts == 0 {
367				return true
368			}
369			return p.procState.Restarts < p.procConf.RestartPolicy.MaxRestarts
370		}
371	
372		// TODO consider if forking daemon should disable RestartPolicyAlways
373		if p.procConf.RestartPolicy.Restart == types.RestartPolicyAlways {
374			if p.procConf.RestartPolicy.MaxRestarts == 0 {
375				return true
376			}
377			return p.procState.Restarts < p.procConf.RestartPolicy.MaxRestarts
378		}
379	
380		return false
381	}
382	
383	// The wait* functions below are used by dependent processes to block until this
384	// process reaches some condition. They all accept an abort channel belonging to
385	// the *waiting* process (its procRunCtx.Done()), so that stopping a process
386	// that is still waiting on its dependencies releases it immediately instead of
387	// leaving its goroutine parked until the dependency happens to resolve.
388	func (p *Process) waitForStarted(abort <-chan struct{}) {
389		select {
390		case <-p.procStartedChan:
391		case <-p.procRunCtx.Done():
392		case <-abort:
393		}
394	}
395	
396	func (p *Process) waitForCompletion() int {
397		p.Lock()
398		defer p.Unlock()
399	
400		for !p.done {
401			p.procCond.Wait()
402		}
403		return p.getExitCode()
404	}
405	
406	// waitForCompletionOrAbort is the abortable flavour of waitForCompletion.
407	func (p *Process) waitForCompletionOrAbort(abort <-chan struct{}) (int, waitResult) {
408		select {
409		case <-p.procDoneChan:
410			return p.getExitCode(), waitOk
411		case <-abort:
412			return 0, waitAborted
413		}
414	}
415	
416	// waitUntilReady waits until the process is ready now, not merely ready at some
417	// point in the past: a running process can lose readiness to a nonfatal probe
418	// failure and regain it later. It fails only once the process can no longer
419	// become ready.
420	func (p *Process) waitUntilReady(abort <-chan struct{}) waitResult {
421		for {
422			p.stateMtx.Lock()
423			health, final, changed := p.procState.Health, p.wontBeReady, p.readyChangedLocked()
424			p.stateMtx.Unlock()
425			// Checked before final, so a process that exited while ready still
426			// satisfies its dependents.
427			if health == types.ProcessHealthReady {
428				return waitOk
429			}
430			if final {
431				log.Error().Msgf("Process %s was aborted and won't become ready", p.getName())
432				p.setExitCode(1)
433				return waitFailed
434			}
435			select {
436			case <-changed:
437			case <-abort:
438				return waitAborted
439			}
440		}
441	}
442	
443	func (p *Process) waitUntilLogReady(abort <-chan struct{}) waitResult {
444		select {
445		case <-p.procLogReadyCtx.Done():
446		case <-abort:
447			return waitAborted
448		}
449		err := context.Cause(p.procLogReadyCtx)
450		if errors.Is(err, context.Canceled) {
451			return waitOk
452		}
453		log.Error().Err(err).Msgf("Process %s was aborted and won't become log ready", p.getName())
454		return waitFailed
455	}
456	
457	// waitUntilTerminated blocks until the goroutine that owns this process (the
458	// one started by ProjectRunner.runProcess) has exited, or until the timeout
459	// elapses. It reports whether the goroutine is gone.
460	func (p *Process) waitUntilTerminated(timeout time.Duration) bool {
461		if p.procTerminatedChan == nil {
462			return true
463		}
464		timer := time.NewTimer(timeout)
465		defer timer.Stop()
466		select {
467		case <-p.procTerminatedChan:
468			return true
469		case <-timer.C:
470			return false
471		}
472	}
473	
474	// onTerminated marks the owning goroutine as gone. Safe to call once.
475	func (p *Process) onTerminated() {
476		if p.procTerminatedChan != nil {
477			close(p.procTerminatedChan)
478		}
479	}
