497	// perform graceful process shutdown if defined in configuration
498	func (p *Process) shutDownNoRestart() error {
499		p.prepareForShutDown()
500		return p.shutDown()
501	}
502	
503	// markRestarting records that this incarnation is being torn down to make way
504	// for a replacement, rather than ending on its own.
505	//
506	// The distinction matters because every exit routes through onProcessEnd, which
507	// shuts the whole project down under exit_on_end or exit_on_failure. A
508	// SIGTERM'd process does not exit 0, so without this marker a restart would
509	// look exactly like a failure and take the project with it.
510	//
511	// Unlike isStopped, this flag is not consumed by isRestartable - it is read
512	// once the process has fully exited.
513	func (p *Process) markRestarting() {
514		p.isRestarting.Store(true)
515	}
516	
517	// isBeingRestarted reports whether this incarnation's exit was caused by an
518	// intentional restart.
519	func (p *Process) isBeingRestarted() bool {
520		return p.isRestarting.Load()
521	}
522	
523	// perform graceful process shutdown if defined in configuration
524	func (p *Process) shutDown() error {
525		return p.stopProcess(true)
526	}
527	
528	// internal stop for graceful shutdown in case of readiness probe failure
529	func (p *Process) internalStop() error {
530		return p.stopProcess(false)
531	}
532	
533	func (p *Process) sendSignal(sig int) error {
534		if !p.isSignalable() {
535			return fmt.Errorf("process %s is not running", p.getName())
536		}
537		return p.command.Stop(sig, p.procConf.ShutDownParams.ParentOnly)
538	}
539	
540	func (p *Process) stopProcess(withNoRestart bool) error {
541		if withNoRestart {
542			p.runCancelFn()
543		}
544		if !p.isRunning() {
545			log.Debug().Msgf("process %s is in state %s not shutting down", p.getName(), p.getStatusName())
546			// prevent pending process from running
547			if p.isOneOfStates(types.ProcessStatePending) {
548				p.onProcessEnd(types.ProcessStateTerminating)
549			}
550			if withNoRestart {
551				p.cancelReadyLogFunc(fmt.Errorf("process %s completed, cannot produce log lines", p.getName()))
552			}
553			return nil
554		}
555		p.setState(types.ProcessStateTerminating)
556		// if the process is interactive and running in the background, it might be blocked on writing to the pty
557		// so we need to drain the pty to allow it to exit
558		if ptyFile := p.command.GetPty(); ptyFile != nil {
559			go func() {
560				_, _ = io.Copy(io.Discard, ptyFile)
561			}()
562		}
563		p.stopProbes()
564		if withNoRestart {
565			p.markWontBeReady()
566			p.cancelReadyLogFunc(fmt.Errorf("process %s was shut down", p.getName()))
567		}
568		if isStringDefined(p.procConf.ShutDownParams.ShutDownCommand) {
569			return p.doConfiguredStop(p.procConf.ShutDownParams)
570		}
571		if isStringDefined(p.procConf.ShutDownParams.SendKeys) {
572			return p.doSendKeysStop(p.procConf.ShutDownParams)
573		}
574		err := p.command.Stop(p.procConf.ShutDownParams.Signal, p.procConf.ShutDownParams.ParentOnly)
575		if err != nil {
576			log.Error().Err(err).Msgf("terminating %s failed", p.getName())
577		}
578		if p.procConf.ShutDownParams.ShutDownTimeout != UndefinedShutdownTimeoutSec {
579			return p.forceKillOnTimeout()
580		}
581		return err
582	}
583	
584	func (p *Process) forceKillOnTimeout() error {
585		if p.waitForStopped(p.procConf.ShutDownParams.ShutDownTimeout) {
586			return nil
587		}
588		log.Debug().Msgf("process failed to shut down within %d seconds, sending %d", p.procConf.ShutDownParams.ShutDownTimeout, syscall.SIGKILL)
589		return p.forceKill()
590	}
591	
592	// waitForStopped waits up to timeout seconds for the process to end and reports
593	// whether it did. It waits on procDoneChan, which stays closed once the process
594	// has ended, so an exit that happens before the wait starts is not missed.
595	func (p *Process) waitForStopped(timeout int) bool {
596		timer := time.NewTimer(time.Duration(timeout) * time.Second)
597		defer timer.Stop()
598		select {
599		case <-p.procDoneChan:
600			return true
601		case <-timer.C:
602			return false
603		}
604	}
605	
606	// forceKill sends SIGKILL to the process group. ESRCH means there is nothing
607	// left to kill because the process exited just as the timeout expired.
608	func (p *Process) forceKill() error {
609		err := p.command.Stop(int(syscall.SIGKILL), false)
610		if errors.Is(err, syscall.ESRCH) {
611			return nil
612		}
613		return err
614	}
615	
616	func (p *Process) doConfiguredStop(params types.ShutDownParams) error {
617		timeout := params.ShutDownTimeout
618		if timeout == UndefinedShutdownTimeoutSec {
619			timeout = DefaultShutdownTimeoutSec
620		}
621		log.Debug().Msgf("terminating %s with timeout %d ...", p.getName(), timeout)
622		ctx, cancel := context.WithTimeout(context.Background(), time.Duration(timeout)*time.Second)
623		defer cancel()
624		defer p.notifyDaemonStopped()
625	
626		cmd := command.BuildCommandShellArgContext(ctx, p.shellConfig, params.ShutDownCommand)
627		cmd.SetEnv(p.getProcessEnvironment())
628		cmd.SetDir(p.procConf.WorkingDir)
629	
630		if err := cmd.Run(); err != nil {
631			// the process termination timedout and it will be killed
632			log.Error().Msgf("terminating %s with timeout %d failed - %s", p.getName(), timeout, err.Error())
633			return p.command.Stop(int(syscall.SIGKILL), false)
634		}
635		return nil
636	}
