716	func (p *Process) onProcessEnd(state string) {
717		if isStringDefined(p.procConf.LogLocation) {
718			p.logger.Close()
719		}
720		p.cancelReadyLogFunc(fmt.Errorf("process %s completed", p.getName()))
721		p.stopProbes()
722		p.markWontBeReady()
723		p.setStateNoPublish(state)
724		p.updateProcState()
725	
726		p.stateMtx.Lock()
727		if p.procState.ProcessEndTime == nil {
728			now := time.Now()
729			p.procState.ProcessEndTime = &now
730		}
731		ev := p.snapshotEventLocked()
732		p.stateMtx.Unlock()
733		// Single publish carrying the terminal Status, final IsRunning=false
734		// (set by updateProcState), final ExitCode, and ProcessEndTime.
735		p.publishLocked(ev)
736	
737		p.Lock()
738		p.done = true
739		p.Unlock()
740		p.procCond.Broadcast()
741		// Release anyone waiting on us through a select-able channel. onProcessEnd
742		// can be reached more than once for the same instance (e.g. a Pending
743		// process that is stopped and later shut down again), hence the Once.
744		p.doneOnce.Do(func() {
745			if p.procDoneChan != nil {
746				close(p.procDoneChan)
747			}
748		})
749	}
