870	// getResourceUsage returns the memory and cpu usage of the process
871	// if the process is not running, returns -1 for both values
872	func (p *Process) getProcResources(proc *puproc.Process) (int64, float64) {
873		memoryInfo, err := proc.MemoryInfo()
874		if err != nil {
875			//log.Err(err).
876			//	Str("process", p.getName()).
877			//	Int("pid", p.procState.Pid).
878			//	Msg("Error retrieving memory stats")
879			return -1, -1
880		}
881		cpuPercent, err := proc.PercentWithContext(context.Background(), 0)
882		if err != nil {
883			log.Err(err).
884				Str("process", p.getName()).
885				Int("pid", p.procState.Pid).
886				Msg("Error retrieving cpu stats")
887			return int64(memoryInfo.RSS), -1
888		}
889		return int64(memoryInfo.RSS), cpuPercent
890	}
