936	func (p *Process) checkElevatedProcOutput(line string) {
937		if p.procConf.IsElevated &&
938			!p.passProvided {
939			if p.waitForPassCancelFn != nil {
940				if isWrongPasswordEntered(line) {
941					log.Warn().
942						Str("process", p.getName()).
943						Msgf("Password rejected %s", line)
944				} else {
945					log.Info().
946						Str("process", p.getName()).
947						Msg("Password accepted")
948					p.passProvided = true
949				}
950				p.waitForPassCancelFn()
951				p.waitForPassCancelFn = nil
952			} else {
953				p.passProvided = true
954			}
955		}
956	}
