1164	func (p *Process) onReadinessCheckEnd(isOk, isFatal bool, err string, details any) {
1165		if isFatal {
1166			p.setProcHealth(types.ProcessHealthNotReady)
1167			p.logBuffer.Write("Error: readiness check fail - " + err)
1168			_ = p.internalStop()
1169		} else if isOk {
