1174	
1175		procHealth := types.ProcessHealthUnknown
1176		p.getStateData(func(state *types.ProcessState) {
1177			procHealth = state.Health
1178		})
1179	
1180		//log exec error if not healthy and output is not empty
1181		if procHealth == types.ProcessHealthNotReady {
1182			rcMap, ok := details.(map[string]string)
1183			if ok {
1184				p.printDetails(rcMap, err, "readiness")
1185			}
