1223	func (p *Process) getOpenPorts(ports *types.ProcessPorts) error {
1224		pids := p.collectPortPids()
1225		if err := p.collectSockets("TCP", netstat.TCPSocks, netstat.TCP6Socks, func(s *netstat.SockTabEntry) bool {
1226			return s.State == netstat.Listen
1227		}, pids, &ports.TcpPorts); err != nil {
1228			return err
1229		}
1230	
1231		return p.collectSockets("UDP", netstat.UDPSocks, netstat.UDP6Socks, func(s *netstat.SockTabEntry) bool {
1232			return s.RemoteAddr != nil && s.RemoteAddr.Port == 0
1233		}, pids, &ports.UdpPorts)
1234	}
