1236	func (p *Process) collectSockets(label string, v4, v6 func(netstat.AcceptFn) ([]netstat.SockTabEntry, error), filter netstat.AcceptFn, pids map[int]struct{}, target *[]uint16) error {
1237		socks, err := v4(filter)
1238		if err != nil {
1239			log.Err(err).Msgf("failed to get open %s ports for %s", label, p.getName())
1240			return err
1241		}
1242		socks6, err := v6(filter)
1243		if err != nil {
1244			log.Err(err).Msgf("failed to get open %s ports for %s", label, p.getName())
1245			return err
1246		}
1247		socks = append(socks, socks6...)
1248	
1249		for _, e := range socks {
1250			if e.Process == nil {
1251				continue
1252			}
1253			if _, ok := pids[e.Process.Pid]; !ok {
1254				continue
1255			}
1256			p.logOpenPort(label, e.LocalAddr.Port)
1257			*target = append(*target, e.LocalAddr.Port)
1258		}
1259		return nil
1260	}
1261	
1262	func (p *Process) logOpenPort(label string, port uint16) {
1263		if label == "UDP" {
1264			log.Debug().Msgf("%s is listening on %d/udp", p.getName(), port)
1265			return
1266		}
1267		log.Debug().Msgf("%s is listening on %d", p.getName(), port)
1268	}
1269	
1270	func (p *Process) getExitCode() int {
1271		p.stateMtx.Lock()
1272		defer p.stateMtx.Unlock()
1273		return p.procState.ExitCode
1274	}
1275	
1276	func (p *Process) setExitCode(code int) {
1277		p.stateMtx.Lock()
1278		defer p.stateMtx.Unlock()
1279		p.procState.ExitCode = code
1280	}
1281	
1282	// setExitCodeLocked sets the exit code when stateMtx is already held.
1283	func (p *Process) setExitCodeLocked(code int) {
1284		p.procState.ExitCode = code
1285	}
1286	
1287	func (p *Process) setProcHealth(health string) {
1288		p.stateMtx.Lock()
1289		prev := p.procState.Health
1290		p.procState.Health = health
1291		if health == types.ProcessHealthReady && p.procState.ProcessReadyTime == nil {
1292			now := time.Now()
1293			p.procState.ProcessReadyTime = &now
1294		}
1295		changed := prev != health
1296		var ev types.ProcessStateEvent
1297		if changed {
1298			ev = p.snapshotEventLocked()
1299			if health == types.ProcessHealthReady {
1300				p.notifyReadinessLocked()
1301			}
1302		}
1303		p.stateMtx.Unlock()
1304		if changed {
1305			p.publishLocked(ev)
1306		}
1307	}
1308	
1309	// markWontBeReady records that the process can no longer become ready and
1310	// releases every waitUntilReady.
1311	func (p *Process) markWontBeReady() {
1312		p.stateMtx.Lock()
1313		defer p.stateMtx.Unlock()
1314		if !p.wontBeReady {
1315			p.wontBeReady = true
1316			p.notifyReadinessLocked()
1317		}
1318	}
1319	
1320	// readyChangedLocked returns the channel closed by the next readiness change:
1321	// the process becoming ready, or wontBeReady being set. It is created on
1322	// demand. The caller must hold stateMtx.
1323	func (p *Process) readyChangedLocked() <-chan struct{} {
1324		if p.readyChangedCh == nil {
1325			p.readyChangedCh = make(chan struct{})
1326		}
1327		return p.readyChangedCh
1328	}
1329	
1330	// notifyReadinessLocked wakes every waitUntilReady to re-evaluate readiness.
1331	// The caller must hold stateMtx.
1332	func (p *Process) notifyReadinessLocked() {
1333		if p.readyChangedCh != nil {
1334			close(p.readyChangedCh)
1335			p.readyChangedCh = nil
1336		}
1337	}
1338	
1339	// set elevated process password
1340	func (p *Process) setPassword(password string) error {
1341		if p.procConf.IsElevated && !p.passProvided && p.stdin != nil {
1342			log.Debug().Msgf(`Set password for elevated process %s`, p.getName())
1343			p.waitForPassCtx, p.waitForPassCancelFn = context.WithTimeout(context.Background(), 4*time.Second)
1344			_, err := p.stdin.Write([]byte(password + "\n"))
1345			if err != nil {
1346				log.Error().Err(err).Msgf(`Failed to write to stdin pipe for process %s`, p.getName())
1347				return err
1348			}
1349			// wait for password confirmation
1350			err = p.waitForPass()
1351			if err != nil {
1352				return err
1353			}
1354		}
1355		return nil
1356	}
1357	
1358	func (p *Process) waitForPass() error {
1359		<-p.waitForPassCtx.Done()
1360		if !p.passProvided {
1361			return fmt.Errorf("wrong password for elevated process %s, %s", p.getName(), p.waitForPassCtx.Err())
1362		}
1363		return nil
1364	}
1365	
1366	func isWrongPasswordEntered(output string) bool {
1367		if runtime.GOOS != "windows" {
1368			return strings.Contains(output, "Sorry, try again")
1369		} else {
1370			return strings.Contains(output, "The user name or password is incorrect")
1371		}
1372	}
1373	
1374	func (p *Process) cancelReadyLogFunc(err error) {
1375		p.mtxStopFn.Lock()
1376		defer p.mtxStopFn.Unlock()
1377		if p.readyLogCancelFn != nil {
1378			p.readyLogCancelFn(err)
1379			p.readyLogCancelFn = nil
1380		}
1381	}
