package app

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"runtime"
	"slices"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/f1bonacc1/netstat/netstat"
	"github.com/f1bonacc1/process-compose/src/types"

	"github.com/f1bonacc1/process-compose/src/command"
	"github.com/f1bonacc1/process-compose/src/health"
	"github.com/f1bonacc1/process-compose/src/pclog"

	"github.com/fatih/color"
	"github.com/rs/zerolog/log"
	puproc "github.com/shirou/gopsutil/v4/process"
)

const (
	UndefinedShutdownTimeoutSec = 0
	DefaultShutdownTimeoutSec   = 10
	EnvReplicaNum               = "PC_REPLICA_NUM"
	LogReplicaNum               = "{" + EnvReplicaNum + "}"
)

type Process struct {
	sync.Mutex
	globalEnv            []string
	procConf             *types.ProcessConfig
	procState            *types.ProcessState
	stateMtx             sync.Mutex
	procCond             sync.Cond
	procStartedChan      chan struct{}
	procStateChan        chan string
	readyChangedCh       chan struct{} // guarded by stateMtx, see readyChangedLocked
	wontBeReady          bool          // guarded by stateMtx, see markWontBeReady
	procLogReadyCtx      context.Context
	readyLogCancelFn     context.CancelCauseFunc
	procRunCtx           context.Context
	runCancelFn          context.CancelFunc
	procDoneChan         chan struct{}
	doneOnce             sync.Once
	procTerminatedChan   chan struct{}
	waitForPassCtx       context.Context
	waitForPassCancelFn  context.CancelFunc
	mtxStopFn            sync.Mutex
	procColor            func(a ...any) string
	noColor              func(a ...any) string
	redColor             func(a ...any) string
	logBuffer            *pclog.ProcessLogBuffer
	logger               pclog.PcLogger
	command              command.Commander
	started              bool
	done                 bool
	timeMutex            sync.Mutex
	startTime            time.Time
	liveProber           *health.Prober
	readyProber          *health.Prober
	shellConfig          command.ShellConfig
	printLogs            bool
	isMain               bool
	extraArgs            []string
	isStopped            atomic.Bool
	isRestarting         atomic.Bool
	stdin                io.WriteCloser
	passProvided         bool
	isTuiEnabled         bool
	stdOutDone           chan struct{}
	stdErrDone           chan struct{}
	dotEnvVars           map[string]string
	truncateLogs         bool
	metricsProc          *puproc.Process
	lastStatusPoll       time.Time
	refRate              time.Duration
	withRecursiveMetrics bool
	processTree          *ProcessTree
	publishState         StatePublisher
}

// StatePublisher is invoked from Process whenever the observable state of
// the process changes. It is supplied by the owner (typically ProjectRunner)
// and may be nil — Process treats that as a no-op.
type StatePublisher func(ev types.ProcessStateEvent)

// waitResult reports how a wait on another process ended.
type waitResult int

const (
	// waitOk - the awaited condition was met.
	waitOk waitResult = iota
	// waitFailed - the awaited process terminated without meeting the condition.
	waitFailed
	// waitAborted - the *waiting* process was shut down before the condition
	// was met, so it must not run at all.
	waitAborted
)

func NewProcess(opts ...ProcOpts) *Process {
	proc := &Process{
		redColor:           color.New(color.FgHiRed).SprintFunc(),
		noColor:            color.New(color.Reset).SprintFunc(),
		started:            false,
		done:               false,
		procStateChan:      make(chan string, 1),
		procStartedChan:    make(chan struct{}, 1),
		procDoneChan:       make(chan struct{}),
		procTerminatedChan: make(chan struct{}),
	}

	for _, opt := range opts {
		opt(proc)
	}
	proc.procColor = pclog.Name2Color(proc.getName())

	proc.procLogReadyCtx, proc.readyLogCancelFn = context.WithCancelCause(context.Background())
	proc.procRunCtx, proc.runCancelFn = context.WithCancel(context.Background())
	proc.setUpProbes()
	proc.procCond = *sync.NewCond(proc)
	return proc
}

func (p *Process) run() int {
	if p.isState(types.ProcessStateTerminating) {
		select {
		case <-p.procRunCtx.Done():
			// Concurrent stop in progress — honour it.
			return 0
		default:
			// Stale "Terminating" state from a prior broken shutdown (e.g. zombie
			// that was reaped without completing the normal lifecycle). Reset so
			// the process can start fresh.
			log.Warn().Str("process", p.getName()).
				Msg("Resetting stale Terminating state before start")
			p.setState(types.ProcessStatePending)
		}
	}

	if err := p.validateProcess(); err != nil {
		log.Error().Err(err).Msgf(`Failed to run command ["%v"] for process %s`, strings.Join(p.getCommand(), `" "`), p.getName())
		p.onProcessEnd(types.ProcessStateError)
		return 1
	}

	p.onProcessStart()
loop:
	for {
		err := p.setStateAndRun(p.getStartingStateName(), p.getProcessStarter())
		if err != nil {
			log.Error().Err(err).Msgf(`Failed to run command ["%v"] for process %s`, strings.Join(p.getCommand(), `" "`), p.getName())
			p.logBuffer.Write(err.Error())
			p.onProcessEnd(types.ProcessStateError)
			return 1
		}

		now := time.Now()
		p.setStartTime(now)
		p.stateMtx.Lock()
		p.procState.Pid = p.command.Pid()
		if p.procState.ProcessStartTime == nil {
			startCopy := now
			p.procState.ProcessStartTime = &startCopy
			// Processes without any readiness signal are considered ready as
			// soon as they start. Probes/log-ready handlers override this later.
			if p.readyProber == nil && p.procConf.ReadyLogLine == "" {
				readyCopy := now
				p.procState.ProcessReadyTime = &readyCopy
			}
		}
		p.metricsProc, err = puproc.NewProcess(int32(p.procState.Pid))
		if err != nil {
			log.Err(err).Msgf("Could not find pid %d with name %s", p.procState.Pid, p.getName())
		}
		p.stateMtx.Unlock()
		log.Info().
			Str("process", p.getName()).
			Strs("command", p.getCommand()).
			Msg("Started")

		p.startProbes()

		p.waitForStdOutErr()
		_ = p.command.Wait()
		p.Lock()
		p.setExitCode(p.command.ExitCode())
		p.Unlock()
		log.Info().
			Str("process", p.getName()).
			Int("exit_code", p.getExitCode()).
			Msg("Exited")

		if p.isDaemonLaunched() {
			p.setState(types.ProcessStateLaunched)
			p.waitForDaemonCompletion()
		}

		if !p.isRestartable() {
			break
		}
		p.setState(types.ProcessStateRestarting)
		p.stateMtx.Lock()
		p.procState.Restarts += 1
		p.stateMtx.Unlock()
		log.Info().Msgf("Restarting %s in %v second(s)... Restarts: %d",
			p.getName(), p.getBackoff().Seconds(), p.procState.Restarts)

		select {
		case <-p.procRunCtx.Done():
			log.Debug().Str("process", p.getName()).Msg("process stopped while waiting to restart")
			break loop
		case <-time.After(p.getBackoff()):
			p.handleInfo("\n")
			continue
		}
	}
	p.onProcessEnd(types.ProcessStateCompleted)
	return p.getExitCode()
}

func (p *Process) waitForStdOutErr() {
	ctx, cancel := context.WithCancel(context.Background())
	if p.procConf.IsDaemon {
		ctx, cancel = context.WithTimeout(context.Background(), time.Duration(p.procConf.LaunchTimeout)*time.Second)
	} else if p.isState(types.ProcessStateTerminating) {
		// In terminating state, never block forever on stdout/stderr drain.
		// Reaching command.Wait() is required to reap child processes.
		timeoutSec := p.procConf.ShutDownParams.ShutDownTimeout
		if timeoutSec == UndefinedShutdownTimeoutSec {
			timeoutSec = DefaultShutdownTimeoutSec
		}
		ctx, cancel = context.WithTimeout(context.Background(), time.Duration(timeoutSec)*time.Second)
	}
	defer cancel()
	if p.stdOutDone != nil {
		select {
		case <-ctx.Done():
			log.Debug().Msgf("%s stdout done with timeout", p.getName())
			return
		case <-p.procRunCtx.Done():
			log.Debug().Msgf("%s stdout abandoned: process stopped", p.getName())
			return
		case <-p.stdOutDone:
			log.Debug().Msgf("%s stdout done", p.getName())
		}
		p.stdOutDone = nil
	}
	if p.stdErrDone != nil {
		select {
		case <-ctx.Done():
			log.Debug().Msgf("%s stderr done with timeout", p.getName())
			return
		case <-p.procRunCtx.Done():
			log.Debug().Msgf("%s stderr abandoned: process stopped", p.getName())
			return
		case <-p.stdErrDone:
			log.Debug().Msgf("%s stderr done", p.getName())
		}
		p.stdErrDone = nil
	}
}

func (p *Process) getProcessStarter() func() error {
	return func() error {
		p.command = p.getCommander()
		p.command.SetEnv(p.getProcessEnvironment())
		p.command.SetDir(p.procConf.WorkingDir)

		if p.isMain || (p.procConf.IsElevated && !p.isTuiEnabled) {
			p.command.AttachIo()
		} else {
			p.command.SetCmdArgs()
			if p.truncateLogs {
				p.logBuffer.Truncate()
			}
			if !p.procConf.IsInteractive {
				stdout, _ := p.command.StdoutPipe()
				p.stdOutDone = make(chan struct{})
				go p.handleOutput(stdout, "stdout", p.handleInfo, p.stdOutDone)
			}
			if !p.procConf.IsTty && !p.procConf.IsInteractive {
				stderr, _ := p.command.StderrPipe()
				p.stdErrDone = make(chan struct{})
				go p.handleOutput(stderr, "stderr", p.handleError, p.stdErrDone)
			}
		}

		if p.procConf.IsElevated && p.isTuiEnabled {
			stdin, err := p.command.StdinPipe()
			if err != nil {
				log.Error().Err(err).Msg("Failed to get stdin pipe")
			}
			p.stdin = stdin
		}

		return p.command.Start()
	}
}

func (p *Process) getCommander() command.Commander {
	if (p.procConf.IsTty || p.procConf.IsInteractive) && !p.isMain {
		return command.BuildPtyCommand(
			p.procConf.Executable,
			p.mergeExtraArgs(),
		)
	} else {
		return command.BuildCommand(
			p.procConf.Executable,
			p.mergeExtraArgs(),
		)
	}

}

func (p *Process) mergeExtraArgs() []string {
	if len(p.extraArgs) == 0 {
		return p.procConf.Args
	}
	tmp := make([]string, len(p.procConf.Args))
	copy(tmp, p.procConf.Args)
	if isStringDefined(p.procConf.Command) {
		lastArg := p.procConf.Args[len(p.procConf.Args)-1]
		lastArg += " " + strings.Join(p.extraArgs, " ")
		return append(tmp[:len(tmp)-1], lastArg)
	} else if len(p.procConf.Entrypoint) > 0 {
		return append(tmp, p.extraArgs...)
	}
	return p.procConf.Args
}

func (p *Process) getBackoff() time.Duration {
	backoff := max(p.procConf.RestartPolicy.BackoffSeconds, 1)
	return time.Duration(backoff) * time.Second
}

func (p *Process) getProcessEnvironment() []string {
	return buildProcessEnvironment(p.procConf, p.globalEnv, p.dotEnvVars)
}

func (p *Process) isRestartable() bool {
	p.Lock()
	exitCode := p.getExitCode()
	p.Unlock()
	if p.isStopped.Swap(false) {
		return false
	}
	if p.procConf.RestartPolicy.Restart == types.RestartPolicyNo {
		return false
	}

	if !p.procConf.IsExitCodeSuccess(exitCode) && p.procConf.RestartPolicy.Restart == types.RestartPolicyExitOnFailure {
		return false
	}

	if !p.procConf.IsExitCodeSuccess(exitCode) && p.procConf.RestartPolicy.Restart == types.RestartPolicyOnFailure {
		if p.procConf.RestartPolicy.MaxRestarts == 0 {
			return true
		}
		return p.procState.Restarts < p.procConf.RestartPolicy.MaxRestarts
	}

	// TODO consider if forking daemon should disable RestartPolicyAlways
	if p.procConf.RestartPolicy.Restart == types.RestartPolicyAlways {
		if p.procConf.RestartPolicy.MaxRestarts == 0 {
			return true
		}
		return p.procState.Restarts < p.procConf.RestartPolicy.MaxRestarts
	}

	return false
}

// The wait* functions below are used by dependent processes to block until this
// process reaches some condition. They all accept an abort channel belonging to
// the *waiting* process (its procRunCtx.Done()), so that stopping a process
// that is still waiting on its dependencies releases it immediately instead of
// leaving its goroutine parked until the dependency happens to resolve.
func (p *Process) waitForStarted(abort <-chan struct{}) {
	select {
	case <-p.procStartedChan:
	case <-p.procRunCtx.Done():
	case <-abort:
	}
}

func (p *Process) waitForCompletion() int {
	p.Lock()
	defer p.Unlock()

	for !p.done {
		p.procCond.Wait()
	}
	return p.getExitCode()
}

// waitForCompletionOrAbort is the abortable flavour of waitForCompletion.
func (p *Process) waitForCompletionOrAbort(abort <-chan struct{}) (int, waitResult) {
	select {
	case <-p.procDoneChan:
		return p.getExitCode(), waitOk
	case <-abort:
		return 0, waitAborted
	}
}

// waitUntilReady waits until the process is ready now, not merely ready at some
// point in the past: a running process can lose readiness to a nonfatal probe
// failure and regain it later. It fails only once the process can no longer
// become ready.
func (p *Process) waitUntilReady(abort <-chan struct{}) waitResult {
	for {
		p.stateMtx.Lock()
		health, final, changed := p.procState.Health, p.wontBeReady, p.readyChangedLocked()
		p.stateMtx.Unlock()
		// Checked before final, so a process that exited while ready still
		// satisfies its dependents.
		if health == types.ProcessHealthReady {
			return waitOk
		}
		if final {
			log.Error().Msgf("Process %s was aborted and won't become ready", p.getName())
			p.setExitCode(1)
			return waitFailed
		}
		select {
		case <-changed:
		case <-abort:
			return waitAborted
		}
	}
}

func (p *Process) waitUntilLogReady(abort <-chan struct{}) waitResult {
	select {
	case <-p.procLogReadyCtx.Done():
	case <-abort:
		return waitAborted
	}
	err := context.Cause(p.procLogReadyCtx)
	if errors.Is(err, context.Canceled) {
		return waitOk
	}
	log.Error().Err(err).Msgf("Process %s was aborted and won't become log ready", p.getName())
	return waitFailed
}

// waitUntilTerminated blocks until the goroutine that owns this process (the
// one started by ProjectRunner.runProcess) has exited, or until the timeout
// elapses. It reports whether the goroutine is gone.
func (p *Process) waitUntilTerminated(timeout time.Duration) bool {
	if p.procTerminatedChan == nil {
		return true
	}
	timer := time.NewTimer(timeout)
	defer timer.Stop()
	select {
	case <-p.procTerminatedChan:
		return true
	case <-timer.C:
		return false
	}
}

// onTerminated marks the owning goroutine as gone. Safe to call once.
func (p *Process) onTerminated() {
	if p.procTerminatedChan != nil {
		close(p.procTerminatedChan)
	}
}

func (p *Process) hasStarted() bool {
	p.Lock()
	defer p.Unlock()
	return p.started
}

func (p *Process) isDone() bool {
	p.Lock()
	defer p.Unlock()
	return p.done
}

func (p *Process) wontRun() {
	p.onProcessEnd(types.ProcessStateSkipped)
}

// perform graceful process shutdown if defined in configuration
func (p *Process) shutDownNoRestart() error {
	p.prepareForShutDown()
	return p.shutDown()
}

// markRestarting records that this incarnation is being torn down to make way
// for a replacement, rather than ending on its own.
//
// The distinction matters because every exit routes through onProcessEnd, which
// shuts the whole project down under exit_on_end or exit_on_failure. A
// SIGTERM'd process does not exit 0, so without this marker a restart would
// look exactly like a failure and take the project with it.
//
// Unlike isStopped, this flag is not consumed by isRestartable - it is read
// once the process has fully exited.
func (p *Process) markRestarting() {
	p.isRestarting.Store(true)
}

// isBeingRestarted reports whether this incarnation's exit was caused by an
// intentional restart.
func (p *Process) isBeingRestarted() bool {
	return p.isRestarting.Load()
}

// perform graceful process shutdown if defined in configuration
func (p *Process) shutDown() error {
	return p.stopProcess(true)
}

// internal stop for graceful shutdown in case of readiness probe failure
func (p *Process) internalStop() error {
	return p.stopProcess(false)
}

func (p *Process) sendSignal(sig int) error {
	if !p.isSignalable() {
		return fmt.Errorf("process %s is not running", p.getName())
	}
	return p.command.Stop(sig, p.procConf.ShutDownParams.ParentOnly)
}

func (p *Process) stopProcess(withNoRestart bool) error {
	if withNoRestart {
		p.runCancelFn()
	}
	if !p.isRunning() {
		log.Debug().Msgf("process %s is in state %s not shutting down", p.getName(), p.getStatusName())
		// prevent pending process from running
		if p.isOneOfStates(types.ProcessStatePending) {
			p.onProcessEnd(types.ProcessStateTerminating)
		}
		if withNoRestart {
			p.cancelReadyLogFunc(fmt.Errorf("process %s completed, cannot produce log lines", p.getName()))
		}
		return nil
	}
	p.setState(types.ProcessStateTerminating)
	// if the process is interactive and running in the background, it might be blocked on writing to the pty
	// so we need to drain the pty to allow it to exit
	if ptyFile := p.command.GetPty(); ptyFile != nil {
		go func() {
			_, _ = io.Copy(io.Discard, ptyFile)
		}()
	}
	p.stopProbes()
	if withNoRestart {
		p.markWontBeReady()
		p.cancelReadyLogFunc(fmt.Errorf("process %s was shut down", p.getName()))
	}
	if isStringDefined(p.procConf.ShutDownParams.ShutDownCommand) {
		return p.doConfiguredStop(p.procConf.ShutDownParams)
	}
	if isStringDefined(p.procConf.ShutDownParams.SendKeys) {
		return p.doSendKeysStop(p.procConf.ShutDownParams)
	}
	err := p.command.Stop(p.procConf.ShutDownParams.Signal, p.procConf.ShutDownParams.ParentOnly)
	if err != nil {
		log.Error().Err(err).Msgf("terminating %s failed", p.getName())
	}
	if p.procConf.ShutDownParams.ShutDownTimeout != UndefinedShutdownTimeoutSec {
		return p.forceKillOnTimeout()
	}
	return err
}

func (p *Process) forceKillOnTimeout() error {
	if p.waitForStopped(p.procConf.ShutDownParams.ShutDownTimeout) {
		return nil
	}
	log.Debug().Msgf("process failed to shut down within %d seconds, sending %d", p.procConf.ShutDownParams.ShutDownTimeout, syscall.SIGKILL)
	return p.forceKill()
}

// waitForStopped waits up to timeout seconds for the process to end and reports
// whether it did. It waits on procDoneChan, which stays closed once the process
// has ended, so an exit that happens before the wait starts is not missed.
func (p *Process) waitForStopped(timeout int) bool {
	timer := time.NewTimer(time.Duration(timeout) * time.Second)
	defer timer.Stop()
	select {
	case <-p.procDoneChan:
		return true
	case <-timer.C:
		return false
	}
}

// forceKill sends SIGKILL to the process group. ESRCH means there is nothing
// left to kill because the process exited just as the timeout expired.
func (p *Process) forceKill() error {
	err := p.command.Stop(int(syscall.SIGKILL), false)
	if errors.Is(err, syscall.ESRCH) {
		return nil
	}
	return err
}

func (p *Process) doConfiguredStop(params types.ShutDownParams) error {
	timeout := params.ShutDownTimeout
	if timeout == UndefinedShutdownTimeoutSec {
		timeout = DefaultShutdownTimeoutSec
	}
	log.Debug().Msgf("terminating %s with timeout %d ...", p.getName(), timeout)
	ctx, cancel := context.WithTimeout(context.Background(), time.Duration(timeout)*time.Second)
	defer cancel()
	defer p.notifyDaemonStopped()

	cmd := command.BuildCommandShellArgContext(ctx, p.shellConfig, params.ShutDownCommand)
	cmd.SetEnv(p.getProcessEnvironment())
	cmd.SetDir(p.procConf.WorkingDir)

	if err := cmd.Run(); err != nil {
		// the process termination timedout and it will be killed
		log.Error().Msgf("terminating %s with timeout %d failed - %s", p.getName(), timeout, err.Error())
		return p.command.Stop(int(syscall.SIGKILL), false)
	}
	return nil
}

// sendKeys writes the interpreted keys to the process's interactive stdin (PTY).
// It returns an error if the process is not interactive (no PTY).
func (p *Process) sendKeys(s string) error {
	pty := p.command.GetPty()
	if pty == nil {
		return fmt.Errorf("process %s is not interactive; cannot send keys", p.getName())
	}
	_, err := pty.Write(interpretKeyEscapes(s))
	return err
}

// doSendKeysStop performs a graceful, key-based shutdown: it writes the
// configured keys to the process's stdin and waits up to the shutdown timeout
// for the process to exit on its own. If it does not exit in time, it is killed
// with SIGKILL (mirroring the shutdown.command fallback behavior).
func (p *Process) doSendKeysStop(params types.ShutDownParams) error {
	if err := p.sendKeys(params.SendKeys); err != nil {
		log.Error().Err(err).Msgf("failed to send keys to %s, falling back to signal", p.getName())
		return p.gracefulShutDownWithSignal(params)
	}
	timeout := params.ShutDownTimeout
	if timeout == UndefinedShutdownTimeoutSec {
		timeout = DefaultShutdownTimeoutSec
	}
	if p.waitForStopped(timeout) {
		return nil // exited gracefully in response to the keys
	}
	log.Debug().Msgf("process %s failed to exit on keys within %d seconds, sending %d", p.getName(), timeout, syscall.SIGKILL)
	return p.forceKill()
}

// gracefulShutDownWithSignal sends the configured signal and applies the
// SIGKILL-on-timeout fallback. It mirrors the default branch of stopProcess and
// is used when send_keys cannot be delivered.
func (p *Process) gracefulShutDownWithSignal(params types.ShutDownParams) error {
	err := p.command.Stop(params.Signal, params.ParentOnly)
	if err != nil {
		log.Error().Err(err).Msgf("terminating %s failed", p.getName())
	}
	if params.ShutDownTimeout != UndefinedShutdownTimeoutSec {
		return p.forceKillOnTimeout()
	}
	return err
}

func (p *Process) isRunning() bool {
	return p.isOneOfStates(
		types.ProcessStateRunning,
		types.ProcessStateLaunched,
		types.ProcessStateLaunching,
	)
}

func (p *Process) isSignalable() bool {
	return p.isOneOfStates(
		types.ProcessStateRunning,
		types.ProcessStateTerminating,
	)
}

func (p *Process) prepareForShutDown() {
	// prevent restart during global shutdown or scale down
	//p.procConf.RestartPolicy.Restart = types.RestartPolicyNo
	p.isStopped.Store(true)

}

func (p *Process) onProcessStart() {
	if isStringDefined(p.procConf.LogLocation) {
		p.logger.Open(p.getLogPath(), p.procConf.LoggerConfig)
	}

	p.Lock()
	p.started = true
	p.Unlock()
	close(p.procStartedChan)
}

func (p *Process) onProcessEnd(state string) {
	if isStringDefined(p.procConf.LogLocation) {
		p.logger.Close()
	}
	p.cancelReadyLogFunc(fmt.Errorf("process %s completed", p.getName()))
	p.stopProbes()
	p.markWontBeReady()
	p.setStateNoPublish(state)
	p.updateProcState()

	p.stateMtx.Lock()
	if p.procState.ProcessEndTime == nil {
		now := time.Now()
		p.procState.ProcessEndTime = &now
	}
	ev := p.snapshotEventLocked()
	p.stateMtx.Unlock()
	// Single publish carrying the terminal Status, final IsRunning=false
	// (set by updateProcState), final ExitCode, and ProcessEndTime.
	p.publishLocked(ev)

	p.Lock()
	p.done = true
	p.Unlock()
	p.procCond.Broadcast()
	// Release anyone waiting on us through a select-able channel. onProcessEnd
	// can be reached more than once for the same instance (e.g. a Pending
	// process that is stopped and later shut down again), hence the Once.
	p.doneOnce.Do(func() {
		if p.procDoneChan != nil {
			close(p.procDoneChan)
		}
	})
}

func (p *Process) getLogPath() string {
	logLocation := p.procConf.LogLocation

	if strings.Contains(logLocation, LogReplicaNum) {
		replicaStr := strconv.Itoa(p.procConf.ReplicaNum)
		logLocation = strings.ReplaceAll(logLocation, LogReplicaNum, replicaStr)
	} else if p.procConf.Replicas > 1 {
		logLocation = fmt.Sprintf("%s.%d", logLocation, p.procConf.ReplicaNum)
	}

	return logLocation
}

func (p *Process) getName() string {
	return p.procConf.ReplicaName
}

func (p *Process) setName(replicaName string) {
	p.procConf.ReplicaName = replicaName
}

func (p *Process) getNameWithSmartReplica() string {
	if p.procConf.Replicas > 1 {
		return p.getName()
	}
	return p.procConf.Name
}

func (p *Process) getCommand() []string {
	return append(
		[]string{(*p.procConf).Executable},
		p.mergeExtraArgs()...,
	)
}

func (p *Process) updateProcState() {
	isRunning := p.isRunning()
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	if isRunning {
		dur := time.Since(p.getStartTime())
		p.procState.SystemTime = HumanDuration(dur)
		p.procState.Age = dur
		p.procState.Name = p.getName()
		if time.Since(p.lastStatusPoll) > p.refRate {
			p.procState.Mem, p.procState.CPU = p.getResourceUsage()
			p.lastStatusPoll = time.Now()
		}
	}
	p.procState.IsRunning = isRunning
	p.procState.IsElevated = p.procConf.IsElevated
	p.procState.PasswordProvided = p.passProvided

}

func (p *Process) setStartTime(startTime time.Time) {
	p.timeMutex.Lock()
	defer p.timeMutex.Unlock()
	p.startTime = startTime
}

func (p *Process) getStartTime() time.Time {
	p.timeMutex.Lock()
	defer p.timeMutex.Unlock()
	return p.startTime
}

func (p *Process) getResourceUsage() (int64, float64) {
	if p.procConf.IsDaemon {
		return -1, -1
	}
	if p.metricsProc == nil {
		return -1, -1
	}
	if p.withRecursiveMetrics {
		return p.getProcResourcesRecursive(p.metricsProc)
	}

	return p.getProcResources(p.metricsProc)
}

// recursively get the memory and cpu usage of the process and its children
func (p *Process) getProcResourcesRecursive(proc *puproc.Process) (int64, float64) {
	totalMem, totalCpu := p.getProcResources(proc)

	if p.processTree == nil {
		childrenProcs, err := proc.Children()
		if err != nil {
			log.Err(err).
				Str("process", p.getName()).
				Int("pid", p.procState.Pid).
				Msg("Error retrieving children")
			return totalMem, totalCpu
		}
		for _, childProc := range childrenProcs {
			childMem, childCpu := p.getProcResourcesRecursive(childProc)
			if childMem >= 0 {
				totalMem += childMem
			}
			if childCpu >= 0 {
				totalCpu += childCpu
			}
		}
		return totalMem, totalCpu
	}

	descendants := p.processTree.GetDescendants(proc.Pid)
	for _, childProc := range descendants {
		childMem, childCpu := p.getProcResources(childProc)
		if childMem >= 0 {
			totalMem += childMem
		}
		if childCpu >= 0 {
			totalCpu += childCpu
		}
	}
	return totalMem, totalCpu
}

// getResourceUsage returns the memory and cpu usage of the process
// if the process is not running, returns -1 for both values
func (p *Process) getProcResources(proc *puproc.Process) (int64, float64) {
	memoryInfo, err := proc.MemoryInfo()
	if err != nil {
		//log.Err(err).
		//	Str("process", p.getName()).
		//	Int("pid", p.procState.Pid).
		//	Msg("Error retrieving memory stats")
		return -1, -1
	}
	cpuPercent, err := proc.PercentWithContext(context.Background(), 0)
	if err != nil {
		log.Err(err).
			Str("process", p.getName()).
			Int("pid", p.procState.Pid).
			Msg("Error retrieving cpu stats")
		return int64(memoryInfo.RSS), -1
	}
	return int64(memoryInfo.RSS), cpuPercent
}

func (p *Process) handleInput(pipe io.WriteCloser) {
	reader := bufio.NewReader(os.Stdin)
	for {
		input, err := reader.ReadString('\n')
		if err != nil {
			log.Err(err).
				Str("process", p.getName()).
				Msg("error reading from stdin")
			continue
		}
		_, _ = pipe.Write([]byte(input))
	}
}

func (p *Process) handleOutput(pipe io.ReadCloser, output string, handler func(message string), done chan struct{}) {
	reader := bufio.NewReader(pipe)
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				break
			}
			var pathErr *os.PathError
			ok := errors.As(err, &pathErr)
			if ok && pathErr.Path == "/dev/ptmx" {
				break
			}
			log.Err(err).
				Str("process", p.getName()).
				Msgf("error reading from %s", output)
			break
		}
		if p.procConf.ReadyLogLine != "" && p.procState.Health == types.ProcessHealthUnknown && strings.Contains(line, p.procConf.ReadyLogLine) {
			// setProcHealth takes stateMtx, updates Health and (for Ready)
			// records ProcessReadyTime atomically.
			p.setProcHealth(types.ProcessHealthReady)
			p.cancelReadyLogFunc(nil)
		}
		p.checkElevatedProcOutput(line)
		handler(strings.TrimSuffix(line, "\n"))
	}
	close(done)
}

func (p *Process) checkElevatedProcOutput(line string) {
	if p.procConf.IsElevated &&
		!p.passProvided {
		if p.waitForPassCancelFn != nil {
			if isWrongPasswordEntered(line) {
				log.Warn().
					Str("process", p.getName()).
					Msgf("Password rejected %s", line)
			} else {
				log.Info().
					Str("process", p.getName()).
					Msg("Password accepted")
				p.passProvided = true
			}
			p.waitForPassCancelFn()
			p.waitForPassCancelFn = nil
		} else {
			p.passProvided = true
		}
	}
}

func (p *Process) handleInfo(message string) {
	p.logger.Info(message, p.getName(), p.procConf.ReplicaNum)
	if p.printLogs {
		fmt.Printf("[%s\t] %s\n", p.procColor(p.getName()), message)
	}
	p.logBuffer.Write(message)
}

func (p *Process) handleError(message string) {
	p.logger.Error(message, p.getName(), p.procConf.ReplicaNum)
	if p.printLogs {
		fmt.Printf("[%s\t] %s\n", p.procColor(p.getName()), p.redColor(message))
	}
	p.logBuffer.Write(message)
}

func (p *Process) isState(state string) bool {
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	return p.procState.Status == state
}

func (p *Process) isOneOfStates(states ...string) bool {
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	return slices.Contains(states, p.procState.Status)
}

func (p *Process) setState(state string) {
	p.stateMtx.Lock()
	p.procState.Status = state
	p.onStateChange(state)
	ev := p.snapshotEventLocked()
	p.stateMtx.Unlock()
	p.publishLocked(ev)
}

// setStateNoPublish sets the state without firing a publish. Use this when
// the caller will publish a single, more complete event afterwards (e.g.
// onProcessEnd, which also finalises ProcessEndTime and IsRunning).
func (p *Process) setStateNoPublish(state string) {
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	p.procState.Status = state
	p.onStateChange(state)
}

// snapshotEventLocked builds a self-contained ProcessStateEvent from the
// current procState. Caller must hold stateMtx.
func (p *Process) snapshotEventLocked() types.ProcessStateEvent {
	stateCopy := *p.procState
	return types.ProcessStateEvent{State: stateCopy}
}

// publishLocked sends the event to the registered publisher, if any. The
// caller must NOT hold stateMtx (the broadcaster fans out under its own
// mutex; observers should not call back into Process, but holding stateMtx
// here would be unnecessary contention).
func (p *Process) publishLocked(ev types.ProcessStateEvent) {
	if p.publishState != nil {
		p.publishState(ev)
	}
}

func (p *Process) getState() *types.ProcessState {
	p.updateProcState()
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	stateCopy := *p.procState
	return &stateCopy
}

type filterFn func(*types.ProcessState)

func (p *Process) getStateData(filter filterFn) {
	p.updateProcState()
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	if filter != nil {
		filter(p.procState)
	}
}

func (p *Process) getStatusName() string {
	p.updateProcState()
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	return p.procState.Status
}

func (p *Process) setStateAndRun(state string, runnable func() error) error {
	p.stateMtx.Lock()
	p.procState.Status = state
	p.onStateChange(state)
	ev := p.snapshotEventLocked()
	defer func() {
		p.stateMtx.Unlock()
		p.publishLocked(ev)
	}()
	return runnable()
}

func (p *Process) GetPty() *os.File {
	if p.command == nil {
		return nil
	}
	return p.command.GetPty()
}

func (p *Process) onStateChange(state string) {
	switch state {
	case types.ProcessStateSkipped:
		p.setExitCodeLocked(1)
	case types.ProcessStateRestarting:
		fallthrough
	case types.ProcessStateLaunching:
		fallthrough
	case types.ProcessStateTerminating:
		p.procState.Health = types.ProcessHealthUnknown
	}
}

func (p *Process) getStartingStateName() string {
	if p.procConf.IsDaemon {
		return types.ProcessStateLaunching
	}
	return types.ProcessStateRunning
}

func (p *Process) setUpProbes() {
	var err error
	if p.procConf.LivenessProbe != nil {
		p.liveProber, err = health.New(
			p.getName()+"_live_probe",
			*p.procConf.LivenessProbe,
			p.getProcessEnvironment(),
			p.shellConfig,
			p.onLivenessCheckEnd,
		)
		if err != nil {
			log.Error().Msgf("failed to setup liveness probe for %s - %s", p.getName(), err.Error())
			p.logBuffer.Write("Error: " + err.Error())
		}
	}

	if p.procConf.ReadinessProbe != nil {
		p.readyProber, err = health.New(
			p.getName()+"_ready_probe",
			*p.procConf.ReadinessProbe,
			p.getProcessEnvironment(),
			p.shellConfig,
			p.onReadinessCheckEnd,
		)
		if err != nil {
			log.Error().Msgf("failed to setup readiness probe for %s - %s", p.getName(), err.Error())
			p.logBuffer.Write("Error: " + err.Error())
		}
	}
}

func (p *Process) startProbes() {
	if p.liveProber != nil {
		p.liveProber.Start()
	}

	if p.readyProber != nil {
		p.readyProber.Start()
	}
}

func (p *Process) stopProbes() {
	if p.liveProber != nil {
		p.liveProber.Stop()
	}

	if p.readyProber != nil {
		p.readyProber.Stop()
	}
}

func (p *Process) onLivenessCheckEnd(_, isFatal bool, err string, details any) {
	if isFatal {
		p.logBuffer.Write("Error: liveness check fail - " + err)
		p.notifyDaemonStopped()
		rcMap, ok := details.(map[string]string)
		if ok {
			p.printDetails(rcMap, err, "liveness")
		}
	}
}

func (p *Process) printDetails(details map[string]string, err, source string) {
	exitCode, _ := strconv.Atoi(details["exit_code"])
	output := details["output"]
	log.Warn().
		Str("error", err).
		Int("exit_code", exitCode).
		Msgf("%s %s probe failed", p.getName(), source)
	if cmd := details["command"]; cmd != "" {
		log.Debug().Msgf("%s %s probe command: %s", p.getName(), source, cmd)
	}
	if output != "" {
		log.Debug().Msgf("%s %s failed with output: %s", p.getName(), source, output)
	}
}

func (p *Process) onReadinessCheckEnd(isOk, isFatal bool, err string, details any) {
	if isFatal {
		p.setProcHealth(types.ProcessHealthNotReady)
		p.logBuffer.Write("Error: readiness check fail - " + err)
		_ = p.internalStop()
	} else if isOk {
		p.setProcHealth(types.ProcessHealthReady)
	} else {
		p.setProcHealth(types.ProcessHealthNotReady)
	}

	procHealth := types.ProcessHealthUnknown
	p.getStateData(func(state *types.ProcessState) {
		procHealth = state.Health
	})

	//log exec error if not healthy and output is not empty
	if procHealth == types.ProcessHealthNotReady {
		rcMap, ok := details.(map[string]string)
		if ok {
			p.printDetails(rcMap, err, "readiness")
		}
	}
}

func (p *Process) validateProcess() error {
	if isStringDefined(p.procConf.WorkingDir) {
		stat, err := os.Stat(p.procConf.WorkingDir)
		if err != nil {
			return err
		}
		if !stat.IsDir() {
			return fmt.Errorf("%s is not a directory", p.procConf.WorkingDir)
		}
	}
	return nil
}

func (p *Process) collectPortPids() map[int]struct{} {
	pids := map[int]struct{}{
		p.procState.Pid: {},
	}
	if p.procState.Pid == 0 {
		return pids
	}
	if p.processTree == nil {
		return pids
	}
	if err := p.processTree.Update(); err != nil {
		log.Err(err).Msgf("failed to update process tree for %s", p.getName())
		return pids
	}
	descendants := p.processTree.GetDescendants(int32(p.procState.Pid))
	for _, proc := range descendants {
		pids[int(proc.Pid)] = struct{}{}
	}
	return pids
}

func (p *Process) getOpenPorts(ports *types.ProcessPorts) error {
	pids := p.collectPortPids()
	if err := p.collectSockets("TCP", netstat.TCPSocks, netstat.TCP6Socks, func(s *netstat.SockTabEntry) bool {
		return s.State == netstat.Listen
	}, pids, &ports.TcpPorts); err != nil {
		return err
	}

	return p.collectSockets("UDP", netstat.UDPSocks, netstat.UDP6Socks, func(s *netstat.SockTabEntry) bool {
		return s.RemoteAddr != nil && s.RemoteAddr.Port == 0
	}, pids, &ports.UdpPorts)
}

func (p *Process) collectSockets(label string, v4, v6 func(netstat.AcceptFn) ([]netstat.SockTabEntry, error), filter netstat.AcceptFn, pids map[int]struct{}, target *[]uint16) error {
	socks, err := v4(filter)
	if err != nil {
		log.Err(err).Msgf("failed to get open %s ports for %s", label, p.getName())
		return err
	}
	socks6, err := v6(filter)
	if err != nil {
		log.Err(err).Msgf("failed to get open %s ports for %s", label, p.getName())
		return err
	}
	socks = append(socks, socks6...)

	for _, e := range socks {
		if e.Process == nil {
			continue
		}
		if _, ok := pids[e.Process.Pid]; !ok {
			continue
		}
		p.logOpenPort(label, e.LocalAddr.Port)
		*target = append(*target, e.LocalAddr.Port)
	}
	return nil
}

func (p *Process) logOpenPort(label string, port uint16) {
	if label == "UDP" {
		log.Debug().Msgf("%s is listening on %d/udp", p.getName(), port)
		return
	}
	log.Debug().Msgf("%s is listening on %d", p.getName(), port)
}

func (p *Process) getExitCode() int {
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	return p.procState.ExitCode
}

func (p *Process) setExitCode(code int) {
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	p.procState.ExitCode = code
}

// setExitCodeLocked sets the exit code when stateMtx is already held.
func (p *Process) setExitCodeLocked(code int) {
	p.procState.ExitCode = code
}

func (p *Process) setProcHealth(health string) {
	p.stateMtx.Lock()
	prev := p.procState.Health
	p.procState.Health = health
	if health == types.ProcessHealthReady && p.procState.ProcessReadyTime == nil {
		now := time.Now()
		p.procState.ProcessReadyTime = &now
	}
	changed := prev != health
	var ev types.ProcessStateEvent
	if changed {
		ev = p.snapshotEventLocked()
		if health == types.ProcessHealthReady {
			p.notifyReadinessLocked()
		}
	}
	p.stateMtx.Unlock()
	if changed {
		p.publishLocked(ev)
	}
}

// markWontBeReady records that the process can no longer become ready and
// releases every waitUntilReady.
func (p *Process) markWontBeReady() {
	p.stateMtx.Lock()
	defer p.stateMtx.Unlock()
	if !p.wontBeReady {
		p.wontBeReady = true
		p.notifyReadinessLocked()
	}
}

// readyChangedLocked returns the channel closed by the next readiness change:
// the process becoming ready, or wontBeReady being set. It is created on
// demand. The caller must hold stateMtx.
func (p *Process) readyChangedLocked() <-chan struct{} {
	if p.readyChangedCh == nil {
		p.readyChangedCh = make(chan struct{})
	}
	return p.readyChangedCh
}

// notifyReadinessLocked wakes every waitUntilReady to re-evaluate readiness.
// The caller must hold stateMtx.
func (p *Process) notifyReadinessLocked() {
	if p.readyChangedCh != nil {
		close(p.readyChangedCh)
		p.readyChangedCh = nil
	}
}

// set elevated process password
func (p *Process) setPassword(password string) error {
	if p.procConf.IsElevated && !p.passProvided && p.stdin != nil {
		log.Debug().Msgf(`Set password for elevated process %s`, p.getName())
		p.waitForPassCtx, p.waitForPassCancelFn = context.WithTimeout(context.Background(), 4*time.Second)
		_, err := p.stdin.Write([]byte(password + "\n"))
		if err != nil {
			log.Error().Err(err).Msgf(`Failed to write to stdin pipe for process %s`, p.getName())
			return err
		}
		// wait for password confirmation
		err = p.waitForPass()
		if err != nil {
			return err
		}
	}
	return nil
}

func (p *Process) waitForPass() error {
	<-p.waitForPassCtx.Done()
	if !p.passProvided {
		return fmt.Errorf("wrong password for elevated process %s, %s", p.getName(), p.waitForPassCtx.Err())
	}
	return nil
}

func isWrongPasswordEntered(output string) bool {
	if runtime.GOOS != "windows" {
		return strings.Contains(output, "Sorry, try again")
	} else {
		return strings.Contains(output, "The user name or password is incorrect")
	}
}

func (p *Process) cancelReadyLogFunc(err error) {
	p.mtxStopFn.Lock()
	defer p.mtxStopFn.Unlock()
	if p.readyLogCancelFn != nil {
		p.readyLogCancelFn(err)
		p.readyLogCancelFn = nil
	}
}

