134	func (p *Process) run() int {
135		if p.isState(types.ProcessStateTerminating) {
136			select {
137			case <-p.procRunCtx.Done():
138				// Concurrent stop in progress — honour it.
139				return 0
140			default:
141				// Stale "Terminating" state from a prior broken shutdown (e.g. zombie
142				// that was reaped without completing the normal lifecycle). Reset so
143				// the process can start fresh.
144				log.Warn().Str("process", p.getName()).
145					Msg("Resetting stale Terminating state before start")
146				p.setState(types.ProcessStatePending)
147			}
148		}
149	
150		if err := p.validateProcess(); err != nil {
151			log.Error().Err(err).Msgf(`Failed to run command ["%v"] for process %s`, strings.Join(p.getCommand(), `" "`), p.getName())
152			p.onProcessEnd(types.ProcessStateError)
153			return 1
154		}
155	
156		p.onProcessStart()
157	loop:
158		for {
159			err := p.setStateAndRun(p.getStartingStateName(), p.getProcessStarter())
160			if err != nil {
161				log.Error().Err(err).Msgf(`Failed to run command ["%v"] for process %s`, strings.Join(p.getCommand(), `" "`), p.getName())
162				p.logBuffer.Write(err.Error())
163				p.onProcessEnd(types.ProcessStateError)
164				return 1
165			}
166	
167			now := time.Now()
168			p.setStartTime(now)
169			p.stateMtx.Lock()
170			p.procState.Pid = p.command.Pid()
171			if p.procState.ProcessStartTime == nil {
172				startCopy := now
173				p.procState.ProcessStartTime = &startCopy
174				// Processes without any readiness signal are considered ready as
175				// soon as they start. Probes/log-ready handlers override this later.
176				if p.readyProber == nil && p.procConf.ReadyLogLine == "" {
177					readyCopy := now
178					p.procState.ProcessReadyTime = &readyCopy
179				}
180			}
181			p.metricsProc, err = puproc.NewProcess(int32(p.procState.Pid))
182			if err != nil {
183				log.Err(err).Msgf("Could not find pid %d with name %s", p.procState.Pid, p.getName())
184			}
185			p.stateMtx.Unlock()
186			log.Info().
187				Str("process", p.getName()).
188				Strs("command", p.getCommand()).
189				Msg("Started")
190	
191			p.startProbes()
192	
193			p.waitForStdOutErr()
194			_ = p.command.Wait()
195			p.Lock()
196			p.setExitCode(p.command.ExitCode())
197			p.Unlock()
198			log.Info().
199				Str("process", p.getName()).
200				Int("exit_code", p.getExitCode()).
201				Msg("Exited")
202	
203			if p.isDaemonLaunched() {
