212			p.stateMtx.Lock()
213			p.procState.Restarts += 1
214			p.stateMtx.Unlock()
215			log.Info().Msgf("Restarting %s in %v second(s)... Restarts: %d",
216				p.getName(), p.getBackoff().Seconds(), p.procState.Restarts)
