236			// In terminating state, never block forever on stdout/stderr drain.
237			// Reaching command.Wait() is required to reap child processes.
238			timeoutSec := p.procConf.ShutDownParams.ShutDownTimeout
239			if timeoutSec == UndefinedShutdownTimeoutSec {
240				timeoutSec = DefaultShutdownTimeoutSec
241			}
242			ctx, cancel = context.WithTimeout(context.Background(), time.Duration(timeoutSec)*time.Second)
243		}
244		defer cancel()
245		if p.stdOutDone != nil {
246			select {
247			case <-ctx.Done():
248				log.Debug().Msgf("%s stdout done with timeout", p.getName())
249				return
250			case <-p.procRunCtx.Done():
251				log.Debug().Msgf("%s stdout abandoned: process stopped", p.getName())
252				return
253			case <-p.stdOutDone:
254				log.Debug().Msgf("%s stdout done", p.getName())
255			}
256			p.stdOutDone = nil
257		}
258		if p.stdErrDone != nil {
