261				log.Debug().Msgf("%s stderr done with timeout", p.getName())
262				return
263			case <-p.procRunCtx.Done():
264				log.Debug().Msgf("%s stderr abandoned: process stopped", p.getName())
265				return
266			case <-p.stdErrDone:
267				log.Debug().Msgf("%s stderr done", p.getName())
268			}
269			p.stdErrDone = nil
270		}
271	}
