356		}
357		if p.procConf.RestartPolicy.Restart == types.RestartPolicyNo {
358			return false
359		}
360	
361		if !p.procConf.IsExitCodeSuccess(exitCode) && p.procConf.RestartPolicy.Restart == types.RestartPolicyExitOnFailure {
362			return false
363		}
364	
365		if !p.procConf.IsExitCodeSuccess(exitCode) && p.procConf.RestartPolicy.Restart == types.RestartPolicyOnFailure {
366			if p.procConf.RestartPolicy.MaxRestarts == 0 {
367				return true
368			}
