370		}
371	
372		// TODO consider if forking daemon should disable RestartPolicyAlways
373		if p.procConf.RestartPolicy.Restart == types.RestartPolicyAlways {
374			if p.procConf.RestartPolicy.MaxRestarts == 0 {
375				return true
376			}
377			return p.procState.Restarts < p.procConf.RestartPolicy.MaxRestarts
378		}
379	
380		return false
381	}
