383	// The wait* functions below are used by dependent processes to block until this
384	// process reaches some condition. They all accept an abort channel belonging to
385	// the *waiting* process (its procRunCtx.Done()), so that stopping a process
386	// that is still waiting on its dependencies releases it immediately instead of
387	// leaving its goroutine parked until the dependency happens to resolve.
388	func (p *Process) waitForStarted(abort <-chan struct{}) {
389		select {
390		case <-p.procStartedChan:
391		case <-p.procRunCtx.Done():
392		case <-abort:
393		}
394	}
