416	// waitUntilReady waits until the process is ready now, not merely ready at some
417	// point in the past: a running process can lose readiness to a nonfatal probe
418	// failure and regain it later. It fails only once the process can no longer
419	// become ready.
420	func (p *Process) waitUntilReady(abort <-chan struct{}) waitResult {
421		for {
422			p.stateMtx.Lock()
423			health, final, changed := p.procState.Health, p.wontBeReady, p.readyChangedLocked()
424			p.stateMtx.Unlock()
425			// Checked before final, so a process that exited while ready still
426			// satisfies its dependents.
427			if health == types.ProcessHealthReady {
428				return waitOk
429			}
430			if final {
431				log.Error().Msgf("Process %s was aborted and won't become ready", p.getName())
432				p.setExitCode(1)
433				return waitFailed
434			}
435			select {
436			case <-changed:
437			case <-abort:
438				return waitAborted
439			}
440		}
441	}
442	
443	func (p *Process) waitUntilLogReady(abort <-chan struct{}) waitResult {
444		select {
445		case <-p.procLogReadyCtx.Done():
446		case <-abort:
447			return waitAborted
448		}
449		err := context.Cause(p.procLogReadyCtx)
450		if errors.Is(err, context.Canceled) {
451			return waitOk
452		}
453		log.Error().Err(err).Msgf("Process %s was aborted and won't become log ready", p.getName())
454		return waitFailed
455	}
