638	// sendKeys writes the interpreted keys to the process's interactive stdin (PTY).
639	// It returns an error if the process is not interactive (no PTY).
640	func (p *Process) sendKeys(s string) error {
641		pty := p.command.GetPty()
642		if pty == nil {
643			return fmt.Errorf("process %s is not interactive; cannot send keys", p.getName())
644		}
645		_, err := pty.Write(interpretKeyEscapes(s))
646		return err
647	}
648	
649	// doSendKeysStop performs a graceful, key-based shutdown: it writes the
650	// configured keys to the process's stdin and waits up to the shutdown timeout
651	// for the process to exit on its own. If it does not exit in time, it is killed
652	// with SIGKILL (mirroring the shutdown.command fallback behavior).
653	func (p *Process) doSendKeysStop(params types.ShutDownParams) error {
654		if err := p.sendKeys(params.SendKeys); err != nil {
655			log.Error().Err(err).Msgf("failed to send keys to %s, falling back to signal", p.getName())
656			return p.gracefulShutDownWithSignal(params)
657		}
658		timeout := params.ShutDownTimeout
659		if timeout == UndefinedShutdownTimeoutSec {
660			timeout = DefaultShutdownTimeoutSec
661		}
662		if p.waitForStopped(timeout) {
663			return nil // exited gracefully in response to the keys
664		}
665		log.Debug().Msgf("process %s failed to exit on keys within %d seconds, sending %d", p.getName(), timeout, syscall.SIGKILL)
666		return p.forceKill()
667	}
668	
669	// gracefulShutDownWithSignal sends the configured signal and applies the
670	// SIGKILL-on-timeout fallback. It mirrors the default branch of stopProcess and
671	// is used when send_keys cannot be delivered.
672	func (p *Process) gracefulShutDownWithSignal(params types.ShutDownParams) error {
673		err := p.command.Stop(params.Signal, params.ParentOnly)
674		if err != nil {
675			log.Error().Err(err).Msgf("terminating %s failed", p.getName())
676		}
677		if params.ShutDownTimeout != UndefinedShutdownTimeoutSec {
678			return p.forceKillOnTimeout()
679		}
680		return err
681	}
