832	// recursively get the memory and cpu usage of the process and its children
833	func (p *Process) getProcResourcesRecursive(proc *puproc.Process) (int64, float64) {
834		totalMem, totalCpu := p.getProcResources(proc)
835	
836		if p.processTree == nil {
837			childrenProcs, err := proc.Children()
838			if err != nil {
839				log.Err(err).
840					Str("process", p.getName()).
841					Int("pid", p.procState.Pid).
842					Msg("Error retrieving children")
843				return totalMem, totalCpu
844			}
845			for _, childProc := range childrenProcs {
846				childMem, childCpu := p.getProcResourcesRecursive(childProc)
847				if childMem >= 0 {
848					totalMem += childMem
849				}
850				if childCpu >= 0 {
851					totalCpu += childCpu
852				}
853			}
854			return totalMem, totalCpu
855		}
856	
857		descendants := p.processTree.GetDescendants(proc.Pid)
858		for _, childProc := range descendants {
859			childMem, childCpu := p.getProcResources(childProc)
860			if childMem >= 0 {
861				totalMem += childMem
862			}
863			if childCpu >= 0 {
864				totalCpu += childCpu
865			}
866		}
867		return totalMem, totalCpu
868	}
