892	func (p *Process) handleInput(pipe io.WriteCloser) {
893		reader := bufio.NewReader(os.Stdin)
894		for {
895			input, err := reader.ReadString('\n')
896			if err != nil {
897				log.Err(err).
898					Str("process", p.getName()).
899					Msg("error reading from stdin")
