906	func (p *Process) handleOutput(pipe io.ReadCloser, output string, handler func(message string), done chan struct{}) {
907		reader := bufio.NewReader(pipe)
908		for {
909			line, err := reader.ReadString('\n')
910			if err != nil {
911				if err == io.EOF {
912					break
913				}
914				var pathErr *os.PathError
915				ok := errors.As(err, &pathErr)
916				if ok && pathErr.Path == "/dev/ptmx" {
917					break
918				}
919				log.Err(err).
920					Str("process", p.getName()).
921					Msgf("error reading from %s", output)
922				break
923			}
924			if p.procConf.ReadyLogLine != "" && p.procState.Health == types.ProcessHealthUnknown && strings.Contains(line, p.procConf.ReadyLogLine) {
925				// setProcHealth takes stateMtx, updates Health and (for Ready)
926				// records ProcessReadyTime atomically.
927				p.setProcHealth(types.ProcessHealthReady)
928				p.cancelReadyLogFunc(nil)
929			}
930			p.checkElevatedProcOutput(line)
931			handler(strings.TrimSuffix(line, "\n"))
932		}
933		close(done)
934	}
