1236	func (p *Process) collectSockets(label string, v4, v6 func(netstat.AcceptFn) ([]netstat.SockTabEntry, error), filter netstat.AcceptFn, pids map[int]struct{}, target *[]uint16) error {
1237		socks, err := v4(filter)
1238		if err != nil {
1239			log.Err(err).Msgf("failed to get open %s ports for %s", label, p.getName())
1240			return err
1241		}
1242		socks6, err := v6(filter)
1243		if err != nil {
1244			log.Err(err).Msgf("failed to get open %s ports for %s", label, p.getName())
1245			return err
1246		}
1247		socks = append(socks, socks6...)
1248	
1249		for _, e := range socks {
1250			if e.Process == nil {
1251				continue
1252			}
1253			if _, ok := pids[e.Process.Pid]; !ok {
1254				continue
1255			}
1256			p.logOpenPort(label, e.LocalAddr.Port)
1257			*target = append(*target, e.LocalAddr.Port)
1258		}
1259		return nil
1260	}
