1340	func (p *Process) setPassword(password string) error {
1341		if p.procConf.IsElevated && !p.passProvided && p.stdin != nil {
1342			log.Debug().Msgf(`Set password for elevated process %s`, p.getName())
1343			p.waitForPassCtx, p.waitForPassCancelFn = context.WithTimeout(context.Background(), 4*time.Second)
1344			_, err := p.stdin.Write([]byte(password + "\n"))
1345			if err != nil {
1346				log.Error().Err(err).Msgf(`Failed to write to stdin pipe for process %s`, p.getName())
1347				return err
1348			}
1349			// wait for password confirmation
1350			err = p.waitForPass()
1351			if err != nil {
1352				return err
1353			}
1354		}
1355		return nil
1356	}
