1222				log.Debug().Msgf("[%s]: waited for all dependencies to shut down", proc.getName())
1223	
1224				err := proc.shutDown()
1225				if err != nil {
1226					log.Err(err).Msgf("failed to shutdown %s", proc.getName())
1227					return
1228				}
1229				proc.waitForCompletion()
1230			}(process)
1231		}
1232	}
1233	
1234	func (p *ProjectRunner) shutDownAndWait(shutdownOrder []*Process) {
1235		wg := sync.WaitGroup{}
1236		if p.isOrderedShutdown {
1237			p.shutDownInOrder(&wg, shutdownOrder)
1238		} else {
1239			for _, proc := range shutdownOrder {
1240				err := proc.shutDown()
1241				if err != nil {
1242					log.Err(err).Msgf("failed to shutdown %s", proc.getName())
1243					continue
1244				}
1245				wg.Add(1)
1246				go func(pr *Process) {
1247					pr.waitForCompletion()
1248					wg.Done()
1249				}(proc)
1250			}
1251		}
1252	
1253		wg.Wait()
1254	}
1255	
1256	func (p *ProjectRunner) ShutDownProject() error {
1257		// Stop watching before anything is torn down: a file touched by a
1258		// shutdown.command must not trigger a restart of a process that is already
1259		// on its way out.
1260		p.stopWatcher()
1261	
1262		p.runProcMutex.Lock()
1263		shutdownOrder := []*Process{}
1264		if p.isOrderedShutdown {
1265			err := p.project.WithProcesses([]string{}, func(process types.ProcessConfig) error {
1266				if runningProc, ok := p.runningProcesses[process.ReplicaName]; ok {
1267					shutdownOrder = append(shutdownOrder, runningProc)
1268				}
1269				return nil
1270			})
1271			if err != nil {
1272				log.Error().Msgf("Failed to build project run order: %s", err.Error())
1273			}
1274			slices.Reverse(shutdownOrder)
1275		} else {
1276			for _, proc := range p.runningProcesses {
1277				shutdownOrder = append(shutdownOrder, proc)
1278			}
1279		}
1280		p.runProcMutex.Unlock()
1281	
1282		var nameOrder []string
1283		for _, v := range shutdownOrder {
1284			nameOrder = append(nameOrder, v.getName())
1285		}
1286		log.Debug().Msgf("Shutting down %d processes. Order: %q", len(shutdownOrder), nameOrder)
1287		for _, proc := range shutdownOrder {
1288			proc.prepareForShutDown()
1289		}
1290	
1291		p.shutDownAndWait(shutdownOrder)
1292		p.cancelAppFn()
1293		return nil
1294	}
