1384	func (p *ProjectRunner) ScaleProcess(name string, scale int) error {
1385		if scale < 1 {
1386			err := fmt.Errorf("cannot scale process %s to a negative or zero value %d", name, scale)
1387			log.Err(err).Msg("scale failed")
1388			return err
1389		}
1390		if processConfig, ok := p.project.Processes[name]; ok {
1391			origScale := p.getCurrentReplicaCount(processConfig.Name)
1392			scaleDelta := scale - origScale
1393			if scaleDelta < 0 {
1394				log.Info().Msgf("scaling down %s by %d", name, -scaleDelta)
1395				p.scaleDownProcess(processConfig.Name, scale)
1396			} else if scaleDelta > 0 {
1397				log.Info().Msgf("scaling up %s by %d", name, scaleDelta)
1398				p.scaleUpProcess(processConfig, scaleDelta, scale, origScale)
1399			} else {
1400				log.Info().Msgf("no change in scale of %s", name)
1401				return nil
1402			}
1403			p.updateReplicaCount(processConfig.Name, scale)
1404		} else {
1405			return fmt.Errorf("no such process: %s", name)
1406		}
1407		return nil
1408	}
