1410	func (p *ProjectRunner) getCurrentReplicaCount(name string) int {
1411		counter := 0
1412		for _, proc := range p.project.Processes {
1413			if proc.Name == name {
1414				counter++
1415			}
1416		}
1417		return counter
1418	}
