1420	func (p *ProjectRunner) scaleUpProcess(proc types.ProcessConfig, toAdd, scale, origScale int) {
1421		for i := range toAdd {
1422			var procFromConf types.ProcessConfig
1423			err := json.Unmarshal([]byte(proc.OriginalConfig), &procFromConf)
1424			if err != nil {
1425				log.Err(err).Msgf("failed to unmarshal config for %s", proc.Name)
1426				return
1427			}
1428			procFromConf.ReplicaNum = origScale + i
1429			procFromConf.Replicas = scale
1430			procFromConf.ReplicaName = procFromConf.CalculateReplicaName()
1431			tpl := templater.New(p.project.Vars)
1432			tpl.RenderProcess(&procFromConf)
1433			if err := tpl.GetError(); err != nil {
1434				log.Err(err).Msgf("failed to render template for %s, field %s", proc.Name, tpl.GetErrorField())
1435				return
1436			}
1437			procFromConf.AssignProcessExecutableAndArgs(p.project.ShellConfig, p.project.GetElevatedShellArg())
1438			p.addProcessAndRun(procFromConf)
1439		}
1440	}
1441	
1442	func (p *ProjectRunner) scaleDownProcess(name string, scale int) {
1443		toRemove := []string{}
1444		p.procConfMutex.Lock()
1445		for _, proc := range p.project.Processes {
1446			if proc.Name == name {
1447				if proc.ReplicaNum >= scale {
1448					toRemove = append(toRemove, proc.ReplicaName)
1449				} else {
1450					proc.Replicas = scale
1451					p.project.Processes[proc.ReplicaName] = proc
1452				}
1453			}
1454		}
1455		p.procConfMutex.Unlock()
1456	
1457		wg := sync.WaitGroup{}
1458		for _, name := range toRemove {
1459			wg.Add(1)
1460			go func(name string) {
1461				defer wg.Done()
1462				if err := p.removeProcess(name); err != nil {
1463					log.Err(err).Msgf("failed to scale down process %s", name)
1464				}
1465			}(name)
1466		}
1467		wg.Wait()
1468	}
1469	
1470	func (p *ProjectRunner) updateReplicaCount(name string, scale int) {
1471		for _, proc := range p.project.Processes {
1472			if proc.Name == name {
1473				proc.Replicas = scale
1474				p.project.Processes[proc.ReplicaName] = proc
1475				if proc.ReplicaName != proc.CalculateReplicaName() {
1476					p.renameProcess(proc.ReplicaName, proc.CalculateReplicaName())
1477				}
1478			}
1479		}
1480	}
1481	
1482	func (p *ProjectRunner) renameProcess(name string, newName string) {
1483		process := p.getRunningProcess(name)
1484		if process != nil {
1485			_, _ = p.removeRunningProcess(process)
1486			process.setName(newName)
1487			p.addRunningProcess(process)
1488		}
1489		logs := p.removeProcessLogs(name)
1490		if logs != nil {
1491			p.processLogs[newName] = logs
1492		}
1493		state, err := p.GetProcessState(name)
1494		if err == nil {
1495			p.statesMutex.Lock()
1496			defer p.statesMutex.Unlock()
1497			delete(p.processStates, name)
1498			state.Name = newName
1499			p.processStates[newName] = state
1500		}
1501		procConf, ok := p.project.Processes[name]
1502		if ok {
1503			delete(p.project.Processes, name)
1504			procConf.ReplicaName = newName
1505			p.project.Processes[newName] = procConf
1506		}
1507		// The watcher is keyed by replica name, and scaling down to 1 renames
1508		// e.g. api-0 to api. Re-key it here, alongside the logs and state above,
1509		// or the watch would be stranded under a name nothing looks up.
1510		p.watchRemove(name)
1511		if ok {
1512			p.watchAdd(&procConf)
1513		}
1514	}
1515	func (p *ProjectRunner) removeProcessLogs(name string) *pclog.ProcessLogBuffer {
1516		p.logsMutex.Lock()
1517		defer p.logsMutex.Unlock()
1518		logs, ok := p.processLogs[name]
1519		if ok {
1520			logs.Close()
1521			delete(p.processLogs, name)
1522		}
1523		return logs
1524	}
1525	
1526	func (p *ProjectRunner) removeProcess(name string) error {
1527		if sched := p.processScheduler.Load(); sched != nil {
1528			if err := sched.RemoveProcess(name); err != nil {
1529				return err
1530			}
1531		}
1532	
1533		p.watchRemove(name)
1534		p.removeProcessLogs(name)
1535		p.procConfMutex.Lock()
1536		delete(p.project.Processes, name)
1537		p.procConfMutex.Unlock()
1538		running := p.getRunningProcess(name)
1539		if running != nil {
1540			err := running.shutDownNoRestart()
1541			if err != nil {
1542				log.Err(err).Msgf("failed to remove process %s", name)
1543				return err
1544			} else {
1545				running.waitForCompletion()
1546			}
1547		}
1548		return nil
1549	}
1550	
1551	func (p *ProjectRunner) addProcessAndRun(proc types.ProcessConfig) {
1552		p.statesMutex.Lock()
1553		p.processStates[proc.ReplicaName] = types.NewProcessState(&proc)
1554		p.statesMutex.Unlock()
1555		p.procConfMutex.Lock()
1556		p.project.Processes[proc.ReplicaName] = proc
1557		p.procConfMutex.Unlock()
1558		// Drop any stale done entry left by a previous incarnation; otherwise
1559		// new dependents would still see the old, cancelled Process object.
1560		p.doneProcMutex.Lock()
1561		delete(p.doneProcesses, proc.ReplicaName)
1562		p.doneProcMutex.Unlock()
1563		p.initProcessLog(proc.ReplicaName)
1564		if proc.Schedule.IsScheduled() {
1565			p.scheduleProcess(proc.ReplicaName, proc)
1566		} else if !proc.IsDeferred() {
1567			p.runProcess(&proc)
1568		}
1569		// UpdateProject routes every add, update and scale-up through here, so this
1570		// single hook keeps the watcher reconciled across reloads.
1571		p.watchAdd(&proc)
1572	}
1573	
1574	// scheduleProcess applies the same schedule registration at startup and reload.
1575	func (p *ProjectRunner) scheduleProcess(name string, proc types.ProcessConfig) {
1576		if !proc.Schedule.IsScheduled() {
1577			return
1578		}
1579		sched := p.processScheduler.Load()
1580		if sched == nil {
1581			return
1582		}
1583		var err error
1584		if proc.Disabled {
1585			err = sched.AddPausedProcess(name, proc.Schedule)
1586		} else {
1587			err = sched.AddProcess(name, proc.Schedule)
1588		}
1589		if err != nil {
1590			log.Error().Err(err).Msgf("Failed to schedule process %s", name)
1591		}
1592	}
1593	
1594	func selectRunningProcesses(project *types.Project, procList []string) error {
1595		if len(procList) == 0 {
1596			return nil
1597		}
1598		newProcMap := types.Processes{}
1599		err := project.WithProcesses(procList, func(process types.ProcessConfig) error {
1600			if process.IsForeground {
1601				return nil
1602			}
1603			newProcMap[process.ReplicaName] = process
1604			return nil
1605		})
1606		if err != nil {
1607			log.Err(err).Msgf("Failed select processes")
1608			return err
1609		}
1610		for name, proc := range project.Processes {
1611			if _, ok := newProcMap[name]; !ok {
1612				proc.Disabled = true
1613			} else {
1614				proc.Disabled = false
1615			}
1616			project.Processes[name] = proc
1617		}
1618		return nil
1619	}
1620	
1621	func selectRunningProcessesNoDeps(project *types.Project, procList []string) error {
1622		if len(procList) == 0 {
1623			return nil
1624		}
1625		for name, proc := range project.Processes {
1626			found := slices.Contains(procList, proc.Name)
1627			if !found {
1628				proc.Disabled = true
1629			} else {
1630				proc.DependsOn = types.DependsOnConfig{}
1631				proc.Disabled = false
1632			}
1633			project.Processes[name] = proc
1634		}
1635	
1636		return nil
1637	}
