1639	// applySelection narrows project to the `up <process>...` selection by
1640	// disabling everything that wasn't selected.
1641	func (p *ProjectRunner) applySelection(project *types.Project) error {
1642		if p.noDeps {
1643			return selectRunningProcessesNoDeps(project, p.processesToRun)
1644		}
1645		return selectRunningProcesses(project, p.processesToRun)
1646	}
1647	
1648	// reapplySelection re-applies the `up <process>...` selection to a freshly
1649	// loaded project, so that a reload or an update doesn't resurrect - and start -
1650	// the processes the user left out. Unlike the initial selection, a name that
1651	// the new configuration no longer defines is dropped instead of failing the
1652	// whole update: that process is about to be removed from the project anyway.
1653	func (p *ProjectRunner) reapplySelection(project *types.Project) error {
1654		if len(p.processesToRun) == 0 {
1655			return nil
1656		}
1657		selected := make([]string, 0, len(p.processesToRun))
1658		for _, name := range p.processesToRun {
1659			if _, err := project.GetProcesses(name); err != nil {
1660				log.Info().Msgf("Selected process %s is no longer defined, dropping it from the selection", name)
1661				continue
1662			}
1663			selected = append(selected, name)
1664		}
1665		if len(selected) == 0 {
1666			// Nothing of the original selection survived. Keep the remaining
1667			// processes deferred rather than starting the entire project.
1668			for name, proc := range project.Processes {
1669				proc.Disabled = true
1670				project.Processes[name] = proc
1671			}
1672			return nil
1673		}
1674		if p.noDeps {
1675			return selectRunningProcessesNoDeps(project, selected)
1676		}
1677		return selectRunningProcesses(project, selected)
1678	}
