1689	func (p *ProjectRunner) GetProjectState(checkMem bool) (*types.ProjectState, error) {
1690		runningProcesses := 0
1691		for name := range p.project.Processes {
1692			state, err := p.GetProcessState(name)
1693			if err != nil {
