1708	func getMemoryUsage() *types.MemoryState {
1709		var m runtime.MemStats
1710		runtime.ReadMemStats(&m)
1711		// For info on each, see: https://golang.org/pkg/runtime/#MemStats
1712		return &types.MemoryState{
1713			Allocated:      bToMb(m.Alloc),
1714			TotalAllocated: bToMb(m.TotalAlloc),
1715			SystemMemory:   bToMb(m.Sys),
1716			GcCycles:       m.NumGC,
1717		}
1718	}
1719	
1720	func bToMb(b uint64) uint64 {
1721		return b / 1024 / 1024
1722	}
