1727		if err != nil {
1728			log.Err(err).Msg("Failed get user")
1729		} else {
1730			username = current.Username
1731		}
1732		runner := &ProjectRunner{
1733			project:              opts.project,
1734			admitters:            opts.admitters,
1735			processesToRun:       opts.processesToRun,
1736			noDeps:               opts.noDeps,
1737			mainProcess:          opts.mainProcess,
1738			mainProcessArgs:      opts.mainProcessArgs,
1739			isTuiOn:              opts.isTuiOn,
1740			isOrderedShutdown:    opts.isOrderedShutdown,
1741			disableDotenv:        opts.disableDotenv,
1742			truncateLogs:         opts.truncateLogs,
1743			refRate:              opts.refRate,
1744			withRecursiveMetrics: opts.withRecursiveMetrics,
1745			noWatch:              opts.noWatch,
1746			projectState: &types.ProjectState{
1747				FileNames: opts.project.FileNames,
1748				StartTime: time.Now(),
1749				UserName:  username,
1750				Version:   config.Version,
1751			},
1752			procCompleteChannel: make(chan int, 128),
1753		}
1754	
1755		name, err := runner.GetProjectName()
1756		if err != nil {
1757			log.Err(err).Msg("Failed get project name")
1758		} else {
1759			runner.projectState.ProjectName = name
1760		}
1761	
1762		if err = runner.applySelection(runner.project); err != nil {
1763			return nil, err
1764		}
1765		runner.projectState.ProcessNum = len(runner.project.Processes)
1766		runner.init()
