1431			tpl := templater.New(p.project.Vars)
1432			tpl.RenderProcess(&procFromConf)
1433			if err := tpl.GetError(); err != nil {
1434				log.Err(err).Msgf("failed to render template for %s, field %s", proc.Name, tpl.GetErrorField())
1435				return
1436			}
1437			procFromConf.AssignProcessExecutableAndArgs(p.project.ShellConfig, p.project.GetElevatedShellArg())
1438			p.addProcessAndRun(procFromConf)
1439		}
1440	}
