1470	func (p *ProjectRunner) updateReplicaCount(name string, scale int) {
1471		for _, proc := range p.project.Processes {
1472			if proc.Name == name {
1473				proc.Replicas = scale
1474				p.project.Processes[proc.ReplicaName] = proc
1475				if proc.ReplicaName != proc.CalculateReplicaName() {
1476					p.renameProcess(proc.ReplicaName, proc.CalculateReplicaName())
1477				}
1478			}
1479		}
1480	}
