1482	func (p *ProjectRunner) renameProcess(name string, newName string) {
1483		process := p.getRunningProcess(name)
1484		if process != nil {
1485			_, _ = p.removeRunningProcess(process)
1486			process.setName(newName)
1487			p.addRunningProcess(process)
1488		}
1489		logs := p.removeProcessLogs(name)
1490		if logs != nil {
1491			p.processLogs[newName] = logs
1492		}
1493		state, err := p.GetProcessState(name)
1494		if err == nil {
1495			p.statesMutex.Lock()
1496			defer p.statesMutex.Unlock()
1497			delete(p.processStates, name)
1498			state.Name = newName
1499			p.processStates[newName] = state
1500		}
1501		procConf, ok := p.project.Processes[name]
1502		if ok {
1503			delete(p.project.Processes, name)
1504			procConf.ReplicaName = newName
1505			p.project.Processes[newName] = procConf
1506		}
1507		// The watcher is keyed by replica name, and scaling down to 1 renames
1508		// e.g. api-0 to api. Re-key it here, alongside the logs and state above,
1509		// or the watch would be stranded under a name nothing looks up.
1510		p.watchRemove(name)
1511		if ok {
1512			p.watchAdd(&procConf)
1513		}
1514	}
1515	func (p *ProjectRunner) removeProcessLogs(name string) *pclog.ProcessLogBuffer {
1516		p.logsMutex.Lock()
1517		defer p.logsMutex.Unlock()
1518		logs, ok := p.processLogs[name]
1519		if ok {
1520			logs.Close()
1521			delete(p.processLogs, name)
1522		}
1523		return logs
1524	}
