1551	func (p *ProjectRunner) addProcessAndRun(proc types.ProcessConfig) {
1552		p.statesMutex.Lock()
1553		p.processStates[proc.ReplicaName] = types.NewProcessState(&proc)
1554		p.statesMutex.Unlock()
1555		p.procConfMutex.Lock()
1556		p.project.Processes[proc.ReplicaName] = proc
1557		p.procConfMutex.Unlock()
1558		// Drop any stale done entry left by a previous incarnation; otherwise
1559		// new dependents would still see the old, cancelled Process object.
1560		p.doneProcMutex.Lock()
1561		delete(p.doneProcesses, proc.ReplicaName)
1562		p.doneProcMutex.Unlock()
1563		p.initProcessLog(proc.ReplicaName)
1564		if proc.Schedule.IsScheduled() {
1565			p.scheduleProcess(proc.ReplicaName, proc)
1566		} else if !proc.IsDeferred() {
1567			p.runProcess(&proc)
1568		}
1569		// UpdateProject routes every add, update and scale-up through here, so this
1570		// single hook keeps the watcher reconciled across reloads.
1571		p.watchAdd(&proc)
1572	}
