1574	// scheduleProcess applies the same schedule registration at startup and reload.
1575	func (p *ProjectRunner) scheduleProcess(name string, proc types.ProcessConfig) {
1576		if !proc.Schedule.IsScheduled() {
1577			return
1578		}
1579		sched := p.processScheduler.Load()
1580		if sched == nil {
1581			return
1582		}
1583		var err error
1584		if proc.Disabled {
1585			err = sched.AddPausedProcess(name, proc.Schedule)
1586		} else {
1587			err = sched.AddProcess(name, proc.Schedule)
1588		}
1589		if err != nil {
1590			log.Error().Err(err).Msgf("Failed to schedule process %s", name)
1591		}
1592	}
