1594	func selectRunningProcesses(project *types.Project, procList []string) error {
1595		if len(procList) == 0 {
1596			return nil
1597		}
1598		newProcMap := types.Processes{}
1599		err := project.WithProcesses(procList, func(process types.ProcessConfig) error {
1600			if process.IsForeground {
1601				return nil
1602			}
1603			newProcMap[process.ReplicaName] = process
1604			return nil
1605		})
1606		if err != nil {
1607			log.Err(err).Msgf("Failed select processes")
1608			return err
1609		}
1610		for name, proc := range project.Processes {
1611			if _, ok := newProcMap[name]; !ok {
1612				proc.Disabled = true
1613			} else {
1614				proc.Disabled = false
1615			}
1616			project.Processes[name] = proc
1617		}
1618		return nil
1619	}
