1621	func selectRunningProcessesNoDeps(project *types.Project, procList []string) error {
1622		if len(procList) == 0 {
1623			return nil
1624		}
1625		for name, proc := range project.Processes {
1626			found := slices.Contains(procList, proc.Name)
1627			if !found {
1628				proc.Disabled = true
1629			} else {
1630				proc.DependsOn = types.DependsOnConfig{}
1631				proc.Disabled = false
1632			}
1633			project.Processes[name] = proc
1634		}
1635	
1636		return nil
1637	}
