1771	// beginUpdate marks a project or process update as in flight. An update stops
1772	// and restarts processes, so while one is running the project must not mistake
1773	// a momentarily empty running set for "all processes are done". Returns the
1774	// function that ends the update.
1775	func (p *ProjectRunner) beginUpdate() func() {
1776		p.updatesInFlight.Add(1)
1777		return func() {
1778			if p.updatesInFlight.Add(-1) != 0 {
1779				return
1780			}
1781			// The update may have removed the last running process for good -
1782			// re-trigger the completion check that was suppressed while it ran.
1783			p.retriggerCompletionCheck()
1784		}
1785	}
1786	
1787	// retriggerCompletionCheck re-runs the project completion check for a project
1788	// with nothing running. The check is skipped while an update or a restart is
1789	// registered, since either is expected to bring a process back; when one ends
1790	// without doing so, the zero count it suppressed has already been consumed, so
1791	// nothing else would ever complete the project.
1792	func (p *ProjectRunner) retriggerCompletionCheck() {
1793		p.runProcMutex.Lock()
1794		running := len(p.runningProcesses)
1795		p.runProcMutex.Unlock()
1796		if running > 0 {
1797			return
1798		}
1799		select {
1800		case p.procCompleteChannel <- 0:
1801		default:
1802		}
1803	}
