1805	func (p *ProjectRunner) UpdateProject(project *types.Project) (map[string]string, error) {
1806		defer p.beginUpdate()()
1807		// Re-apply the load-time admission policies (e.g. --namespace) and the
1808		// `up <process>...` selection so that excluded processes don't get
1809		// resurrected - and started - by a project reload or update.
1810		admitter.ApplyToProject(project, p.admitters)
1811		if err := p.reapplySelection(project); err != nil {
1812			return nil, err
1813		}
1814		newProcs := make(map[string]types.ProcessConfig)
1815		delProcs := make(map[string]types.ProcessConfig)
1816		updatedProcs := make(map[string]types.ProcessConfig)
1817		for name, newProc := range project.Processes {
1818			if currentProc, ok := p.project.Processes[name]; ok {
1819				equal := currentProc.Compare(&newProc)
1820				if equal {
1821					log.Debug().Msgf("Process %s is up to date", name)
1822					continue
1823				}
1824				log.Debug().Msgf("Process %s is updated", name)
1825				updatedProcs[name] = newProc
1826			} else {
1827				log.Debug().Msgf("Process %s is new", name)
1828				newProcs[name] = newProc
1829			}
1830		}
1831		for name, currentProc := range p.project.Processes {
1832			if _, ok := project.Processes[name]; !ok {
1833				log.Debug().Msgf("Process %s is deleted", name)
1834				delProcs[name] = currentProc
1835			}
1836		}
1837		status := make(map[string]string)
1838		errs := make([]error, 0)
1839		//Delete removed processes
1840		for name := range delProcs {
1841			err := p.removeProcess(name)
1842			if err != nil {
1843				log.Err(err).Msgf("Failed to remove process %s", name)
1844				errs = append(errs, err)
1845				status[name] = types.ProcessUpdateError
1846				continue
1847			}
1848			status[name] = types.ProcessUpdateRemoved
1849		}
1850		//Add new processes
1851		for name, proc := range newProcs {
1852			p.addProcessAndRun(proc)
1853			status[name] = types.ProcessUpdateAdded
1854		}
1855		//Update processes
1856		for name, proc := range updatedProcs {
1857			err := p.UpdateProcess(&proc)
1858			if err != nil {
1859				log.Err(err).Msgf("Failed to update process %s", name)
1860				errs = append(errs, err)
1861				status[name] = types.ProcessUpdateError
1862				continue
1863			}
1864			status[name] = types.ProcessUpdateUpdated
1865		}
1866		return status, errors.Join(errs...)
1867	}
