1889	func (p *ProjectRunner) UpdateProcess(updated *types.ProcessConfig) error {
1890		defer p.beginUpdate()()
1891		isScaleChanged := false
1892		validateProbes(updated.LivenessProbe)
1893		validateProbes(updated.ReadinessProbe)
1894		updated.AssignProcessExecutableAndArgs(p.project.ShellConfig, p.project.ShellConfig.ElevatedShellArg)
1895		if currentProc, ok := p.project.Processes[updated.ReplicaName]; ok {
1896			equal := currentProc.Compare(updated)
1897			if equal {
1898				log.Debug().Msgf("Process %s is up to date", updated.Name)
1899				return nil
1900			}
1901			log.Debug().Msgf("Process %s is updated", updated.Name)
1902			if currentProc.Replicas != updated.Replicas {
1903				isScaleChanged = true
1904			}
1905		} else {
1906			err := fmt.Errorf("no such process: %s", updated.ReplicaName)
1907			log.Err(err).Msgf("Failed to update process %s", updated.ReplicaName)
1908			return err
1909		}
1910	
1911		err := p.removeProcess(updated.ReplicaName)
1912		if err != nil {
1913			log.Err(err).Msgf("Failed to remove process %s", updated.ReplicaName)
1914			return err
1915		}
1916		p.addProcessAndRun(*updated)
1917	
1918		if isScaleChanged {
1919			err = p.ScaleProcess(updated.ReplicaName, updated.Replicas)
1920			if err != nil {
1921				log.Err(err).Msgf("Failed to scale process %s", updated.Name)
1922				return err
1923			}
1924		}
1925		return nil
1926	}
