package command

import (
	"context"
	"errors"
	"io"
	"os"
	"os/exec"
	"sync/atomic"
)

type CmdWrapper struct {
	cmd *exec.Cmd
	// childPipes are the write ends of the output pipes handed to the child.
	// The parent must drop its copies once the child holds its own, or the
	// readers would never see EOF.
	childPipes []*os.File
	// groupGone is set once the child's process group is known to be empty.
	// Its ID can be recycled from then on, so nothing may be signalled through
	// it any more.
	groupGone atomic.Bool
}

func (c *CmdWrapper) GetPty() *os.File {
	return nil
}

func (c *CmdWrapper) Start() error {
	err := c.cmd.Start()
	c.closeChildPipes()
	return err
}

func (c *CmdWrapper) Run() error {
	return c.cmd.Run()
}

// Wait blocks until the command itself has exited. It deliberately does not
// wait for - or close - the pipes returned by StdoutPipe and StderrPipe: a
// descendant that inherited them can keep them open long after the command is
// gone, and the exit must still be noticed. Draining them is up to the caller.
func (c *CmdWrapper) Wait() error {
	return c.cmd.Wait()
}

func (c *CmdWrapper) ExitCode() int {
	return exitCode(c.cmd.ProcessState)
}

func (c *CmdWrapper) Pid() int {
	return c.cmd.Process.Pid
}

func (c *CmdWrapper) StdoutPipe() (io.ReadCloser, error) {
	if c.cmd.Stdout != nil {
		return nil, errors.New("command: stdout already set")
	}
	reader, writer, err := c.outputPipe()
	if err != nil {
		return nil, err
	}
	c.cmd.Stdout = writer
	return reader, nil
}

func (c *CmdWrapper) StderrPipe() (io.ReadCloser, error) {
	if c.cmd.Stderr != nil {
		return nil, errors.New("command: stderr already set")
	}
	reader, writer, err := c.outputPipe()
	if err != nil {
		return nil, err
	}
	c.cmd.Stderr = writer
	return reader, nil
}

// outputPipe creates a pipe whose write end goes to the child.
//
// exec.Cmd's own StdoutPipe is not used because Cmd.Wait closes its read end
// the moment the command exits, which forces callers to finish reading before
// they call Wait - and a read only finishes when every holder of the write end
// is gone. A command that leaves a background child behind would then never be
// seen to exit. With a pipe we own, Wait reports the exit right away and the
// read end stays valid for as long as there is something left to read.
func (c *CmdWrapper) outputPipe() (*os.File, *os.File, error) {
	reader, writer, err := os.Pipe()
	if err != nil {
		return nil, nil, err
	}
	c.childPipes = append(c.childPipes, writer)
	return reader, writer, nil
}

func (c *CmdWrapper) closeChildPipes() {
	for _, pipe := range c.childPipes {
		_ = pipe.Close()
	}
	c.childPipes = nil
}

func (c *CmdWrapper) StdinPipe() (io.WriteCloser, error) {
	return c.cmd.StdinPipe()
}

func (c *CmdWrapper) AttachIo() {
	c.cmd.Stdin = os.Stdin
	c.cmd.Stdout = os.Stdout
	c.cmd.Stderr = os.Stderr
}

func (c *CmdWrapper) SetEnv(env []string) {
	c.cmd.Env = env
}

func (c *CmdWrapper) SetDir(dir string) {
	c.cmd.Dir = dir
}

func (c *CmdWrapper) Output() ([]byte, error) {
	return c.cmd.Output()
}

func (c *CmdWrapper) CombinedOutput() ([]byte, error) {
	return c.cmd.CombinedOutput()
}

// WaitGroupExit blocks until no live process is left in the command's process
// group, or until ctx is done. It reports whether the group is gone.
//
// Stopping a command signals its whole group, but the command exiting says
// nothing about the rest of it: a shell wrapper dies on SIGTERM at once while
// the server it launched is still closing its listeners. Only when the group is
// empty have the resources it held - ports above all - actually been released.
func (c *CmdWrapper) WaitGroupExit(ctx context.Context) bool {
	if c.groupGone.Load() {
		return true
	}
	gone := c.waitGroupExit(ctx)
	if gone {
		c.groupGone.Store(true)
	}
	return gone
}
