cat > src/command/stopper_unix.go <<'EOF'
//go:build !windows

package command

import (
	"context"
	"errors"
	"os"
	"syscall"
	"time"

	"github.com/rs/zerolog/log"
)

const (
	min_sig = 1
	max_sig = 31

	// exitCodeSignalBase is added to the signal number to form the exit code
	// of a command that was terminated by a signal - the convention every
	// shell follows (143 for SIGTERM, 137 for SIGKILL).
	exitCodeSignalBase = 128

	groupPollMin = 5 * time.Millisecond
	groupPollMax = 100 * time.Millisecond
)

func (c *CmdWrapper) Stop(sig int, parentOnly bool) error {
	if c.cmd == nil {
		return nil
	}
	if sig < min_sig || sig > max_sig {
		sig = int(syscall.SIGTERM)
	}

	log.
		Debug().
		Int("pid", c.Pid()).
		Int("signal", sig).
		Bool("parentOnly", parentOnly).
		Msg("Stop Unix process.")

	if parentOnly {
		err := c.cmd.Process.Signal(syscall.Signal(sig))
		if errors.Is(err, os.ErrProcessDone) {
			return syscall.ESRCH
		}
		return err
	}

	if c.ownsGroup() {
		// The command leads its own group, so the group ID is its PID. Going
		// through Getpgid instead would fail as soon as the command itself has
		// been reaped, leaving the rest of the group unreachable - exactly when
		// a SIGKILL is needed for whatever outlived it.
		if c.groupGone.Load() {
			return syscall.ESRCH
		}
		return syscall.Kill(-c.Pid(), syscall.Signal(sig))
	}

	pgid, err := syscall.Getpgid(c.Pid())
	if err == nil {
		return syscall.Kill(-pgid, syscall.Signal(sig))
	}

	return err
}

func (c *CmdWrapper) SetCmdArgs() {
	c.cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
}

// ownsGroup reports whether the command was started as the leader of its own
// process group, either directly (Setpgid) or as a session leader (Setsid, the
// PTY case). A command sharing process-compose's own group has no group of its
// own to wait for or to signal by ID.
func (c *CmdWrapper) ownsGroup() bool {
	attr := c.cmd.SysProcAttr
	return attr != nil && c.cmd.Process != nil &&
		((attr.Setpgid && attr.Pgid == 0) || attr.Setsid)
}

func (c *CmdWrapper) waitGroupExit(ctx context.Context) bool {
	if !c.ownsGroup() {
		return true
	}
	pgid := c.Pid()
	interval := groupPollMin
	timer := time.NewTimer(interval)
	defer timer.Stop()
	for {
		if !isGroupAlive(pgid) {
			return true
		}
		select {
		case <-ctx.Done():
			return false
		case <-timer.C:
		}
		interval = min(interval*2, groupPollMax)
		timer.Reset(interval)
	}
}

// isGroupAlive reports whether the process group still has a live member.
