package command

import (
	"bytes"
	"os"
	"strconv"
)

// hasLiveGroupMember reports whether any process in the group is still running,
// as opposed to having exited without being reaped yet. It is only consulted
// once the kernel has confirmed that the group has members at all.
func hasLiveGroupMember(pgid int) bool {
	entries, err := os.ReadDir("/proc")
	if err != nil {
		// Without /proc there is no telling the two apart; believe the kernel.
		return true
	}
	readable := false
	for _, entry := range entries {
		if _, err := strconv.Atoi(entry.Name()); err != nil {
			continue
		}
		stat, err := os.ReadFile("/proc/" + entry.Name() + "/stat")
		if err != nil {
			continue
		}
		state, group, ok := parseProcStat(stat)
		if !ok {
			continue
		}
		readable = true
		if group == pgid && state != 'Z' && state != 'X' {
			return true
		}
	}
	// A /proc that lists nothing we can parse proves nothing either way.
	return !readable
}

// parseProcStat extracts the state and the process group from the contents of
// /proc/<pid>/stat: "pid (comm) state ppid pgrp ...". The command name may hold
// spaces and parentheses of its own, so the fields are located after the last
// closing parenthesis.
func parseProcStat(stat []byte) (state byte, pgrp int, ok bool) {
	end := bytes.LastIndexByte(stat, ')')
	if end < 0 {
		return 0, 0, false
	}
	fields := bytes.Fields(stat[end+1:])
	if len(fields) < 3 || len(fields[0]) != 1 {
		return 0, 0, false
	}
	pgrp, err := strconv.Atoi(string(fields[2]))
	if err != nil {
		return 0, 0, false
	}
	return fields[0][0], pgrp, true
}
