// waitForStopped waits up to timeout seconds for the given launch to be gone
// and reports whether it is. Both channels stay closed once they fire, so an
// exit that happens before the wait starts is not missed.
//
// The wait is tied to the launch rather than to the process as a whole. A
// process that is restarted by its policy after being stopped - as on a failed
// readiness probe - never ends, so waiting for the process would always run out
// the timeout and then kill whatever is running by then: the replacement.
func (p *Process) waitForStopped(inc *incarnation, timeout int) bool {
	timer := time.NewTimer(time.Duration(timeout) * time.Second)
	defer timer.Stop()
	select {
	case <-inc.exited:
		return true
	case <-p.procDoneChan:
		return true
	case <-timer.C:
		return false
	}
}

