package app

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"syscall"
	"testing"
	"time"

	"github.com/f1bonacc1/process-compose/src/command"
	"github.com/f1bonacc1/process-compose/src/health"
	"github.com/f1bonacc1/process-compose/src/pclog"
	"github.com/f1bonacc1/process-compose/src/types"
)

// slowStopServer writes a script standing in for a server that owns an
// exclusive resource - a port, in real life - and takes a while to give it up
// when asked to stop. The resource is a lock directory: a second copy started
// while the first still holds it records a CONFLICT, the way a real server
// would fail with "address already in use".
func slowStopServer(t *testing.T, dir string) (script, events string) {
	t.Helper()
	lock := filepath.Join(dir, "port.lock")
	events = filepath.Join(dir, "events")
	script = filepath.Join(dir, "server.sh")
	body := fmt.Sprintf(`trap 'sleep 0.6; rmdir %[1]q; exit 0' TERM
if ! mkdir %[1]q 2>/dev/null; then
  echo CONFLICT >> %[2]q
  exit 98
fi
echo up >> %[2]q
while :; do sleep 0.05; done
`, lock, events)
	if err := os.WriteFile(script, []byte(body), 0o600); err != nil {
		t.Fatal(err)
	}
	return script, events
}

func readEvents(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		t.Fatal(err)
	}
	return string(data)
}

// A restart must not launch the replacement while the old incarnation is still
// shutting down, or the two fight over whatever the old one has yet to release.
//
// The watch path is the one exercised: it skips backoff, so nothing but an
// explicit wait stands between the stop signal and the relaunch.
func TestRestartWaitsForOldIncarnationToExit(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("relies on Unix signals")
	}
	shell := command.DefaultShellConfig()
	const name = "api"

	tests := []struct {
		name string
		// cmd builds the process command from the server script.
		cmd func(script string) string
	}{
		{
			// The server is the command: its own exit is what has to be awaited.
			name: "server is the command",
			cmd:  func(script string) string { return "exec bash " + script },
		},
		{
			// The server runs under a shell that dies on SIGTERM at once and
			// leaves it behind, as `npm run`, a `cd x && server` one-liner or
			// any launcher script does. The command is gone long before the
			// server is; only its process group tells.
			name: "server is behind a wrapper",
			cmd:  func(script string) string { return "bash " + script + "; true" },
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			script, events := slowStopServer(t, t.TempDir())
			runner, err := NewProjectRunner(&ProjectOpts{
				project: &types.Project{
					ShellConfig: shell,
					Processes: map[string]types.ProcessConfig{
						name: {
							Name:        name,
							ReplicaName: name,
							Executable:  shell.ShellCommand,
							Args:        []string{shell.ShellArgument, tt.cmd(script)},
						},
					},
				},
			})
			if err != nil {
				t.Fatal(err)
			}
			go func() { _ = runner.Run() }()
			t.Cleanup(func() { _ = runner.ShutDownProject() })

			if !waitForLineCount(t, events, 1, 10*time.Second) {
				t.Fatalf("server never came up; events: %q", readEvents(t, events))
			}

			const restarts = 3
			for i := range restarts {
				if err := runner.RestartProcesses([]string{name}); err != nil {
					t.Fatalf("restart %d: %v", i+1, err)
				}
				if !waitForLineCount(t, events, i+2, 10*time.Second) {
					t.Fatalf("restart %d never brought the server back; events: %q", i+1, readEvents(t, events))
				}
			}

			got := readEvents(t, events)
			if strings.Contains(got, "CONFLICT") {
				t.Errorf("a replacement was launched while the old incarnation was still running; events: %q", got)
			}
			if ups := strings.Count(got, "up\n"); ups != restarts+1 {
				t.Errorf("server came up %d times, want %d; events: %q", ups, restarts+1, got)
			}
		})
	}
}

// A restart that is waiting for a process to stop must give up when the project
// shuts down, rather than hold the shutdown hostage - and must not launch
// anything once it has.
func TestRestartWaitEndsWhenProjectShutsDown(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("relies on Unix signals")
	}
	shell := command.DefaultShellConfig()
	const name = "stubborn"
	marker := filepath.Join(t.TempDir(), "starts")

	runner, err := NewProjectRunner(&ProjectOpts{
		project: &types.Project{
			ShellConfig: shell,
			Processes: map[string]types.ProcessConfig{
				name: {
					Name:        name,
					ReplicaName: name,
					Executable:  shell.ShellCommand,
					// Ignores SIGTERM and has no shutdown timeout: it never stops.
					Args: []string{shell.ShellArgument,
						fmt.Sprintf("trap '' TERM; echo up >> %q; while :; do sleep 0.05; done", marker)},
				},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	go func() { _ = runner.Run() }()
	if !waitForLineCount(t, marker, 1, 10*time.Second) {
		t.Fatal("process never started")
	}
	proc := runner.getRunningProcess(name)
	if proc == nil {
		t.Fatal("process is not registered")
	}
	t.Cleanup(func() { _ = proc.command.Stop(int(syscall.SIGKILL), false) })

	restarted := make(chan error, 1)
	go func() { restarted <- runner.RestartProcess(name) }()

	select {
	case err := <-restarted:
		t.Fatalf("restart returned (%v) although the old incarnation is still running", err)
	case <-time.After(500 * time.Millisecond):
	}

	runner.markShuttingDown()
	select {
	case err := <-restarted:
		if !errors.Is(err, errProjectShuttingDown) {
			t.Errorf("restart returned %v, want %v", err, errProjectShuttingDown)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("restart is still waiting after the project began shutting down")
	}
	if got := countLinesIn(t, marker); got != 1 {
		t.Errorf("process was launched %d times, want 1", got)
	}
}

// A process started while the project is shutting down must not be left running
// behind it.
func TestNoLaunchDuringShutdown(t *testing.T) {
	shell := command.DefaultShellConfig()
	const (
		running = "running"
		late    = "late"
	)
	runner, err := NewProjectRunner(&ProjectOpts{
		project: &types.Project{
			ShellConfig: shell,
			Processes: map[string]types.ProcessConfig{
				running: {
					Name:        running,
					ReplicaName: running,
					Executable:  shell.ShellCommand,
					Args:        []string{shell.ShellArgument, getSleepCommand(60)},
				},
				late: {
					Name:        late,
					ReplicaName: late,
					Disabled:    true,
					Executable:  shell.ShellCommand,
					Args:        []string{shell.ShellArgument, getSleepCommand(60)},
				},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	go func() { _ = runner.Run() }()
	t.Cleanup(func() { _ = runner.ShutDownProject() })
	waitForProcessState(t, runner, running, types.ProcessStateRunning, 10*time.Second)

	runner.markShuttingDown()
	if err := runner.StartProcess(late); err != nil {
		t.Fatalf("start: %v", err)
	}
	if !waitForProcessDeregistered(runner, late, 10*time.Second) {
		t.Fatal("a process started during shutdown is still registered")
	}
	state, err := runner.GetProcessState(late)
	if err != nil {
		t.Fatal(err)
	}
	if state.Pid != 0 {
		t.Errorf("a process started during shutdown was launched with pid %d", state.Pid)
	}
}

// A command that exits is done, even if something it started still holds its
// output open. The exit must not be missed, and what depends on it must start.
func TestProcessCompletesWhileItsOutputIsHeldOpen(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("relies on Unix process semantics")
	}
	shell := command.DefaultShellConfig()
	const (
		migrate = "migrate"
		api     = "api"
	)
	runner, err := NewProjectRunner(&ProjectOpts{
		project: &types.Project{
			ShellConfig: shell,
			LogLength:   100,
			Processes: map[string]types.ProcessConfig{
				migrate: {
					Name:        migrate,
					ReplicaName: migrate,
					Executable:  shell.ShellCommand,
					// The helper inherits stdout and stderr and outlives the
					// migration by far.
					Args: []string{shell.ShellArgument, "echo migrating; sleep 60 & echo migrated"},
				},
				api: {
					Name:        api,
					ReplicaName: api,
					Executable:  shell.ShellCommand,
					Args:        []string{shell.ShellArgument, getSleepCommand(60)},
					DependsOn: types.DependsOnConfig{
						migrate: {Condition: types.ProcessConditionCompletedSuccessfully},
					},
				},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	go func() { _ = runner.Run() }()
	t.Cleanup(func() { _ = runner.ShutDownProject() })

	waitForProcessLaunched(t, runner, migrate, 10*time.Second)
	proc := runner.getRunningProcess(migrate)
	if proc != nil {
		// The helper is not ours to stop; reap it by hand once the test is over.
		t.Cleanup(func() { _ = syscall.Kill(-proc.getState().Pid, syscall.SIGKILL) })
	}

	waitForProcessState(t, runner, migrate, types.ProcessStateCompleted, 10*time.Second)
	waitForProcessState(t, runner, api, types.ProcessStateRunning, 10*time.Second)

	state, err := runner.GetProcessState(migrate)
	if err != nil {
		t.Fatal(err)
	}
	if state.ExitCode != 0 {
		t.Errorf("migrate exit code = %d, want 0", state.ExitCode)
	}
	logs, err := runner.GetProcessLog(migrate, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	if joined := strings.Join(logs, "\n"); !strings.Contains(joined, "migrating") || !strings.Contains(joined, "migrated") {
		t.Errorf("output written before the exit was not captured, got %q", logs)
	}
}

// The project exits with the code of the process that ended it. The processes
// terminated by the resulting shutdown exit non-zero too, and must not replace
// that code with their own.
func TestProjectExitCodeIsNotReplacedDuringShutdown(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("uses POSIX shell syntax")
	}
	shell := command.DefaultShellConfig()
	tests := []struct {
		name     string
		testsCmd string
		wantCode int
	}{
		{name: "failing run", testsCmd: "sleep 0.3; exit 3", wantCode: 3},
		{name: "passing run", testsCmd: "sleep 0.3; exit 0", wantCode: 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			processes := map[string]types.ProcessConfig{
				"tests": {
					Name:          "tests",
					ReplicaName:   "tests",
					Executable:    shell.ShellCommand,
					Args:          []string{shell.ShellArgument, tt.testsCmd},
					RestartPolicy: types.RestartPolicyConfig{ExitOnEnd: true},
				},
			}
			// Services that are torn down with the project. Each carries a
			// policy under which its own exit ends the project.
			for _, svc := range []struct {
				name   string
				policy types.RestartPolicyConfig
			}{
				{"db", types.RestartPolicyConfig{Restart: types.RestartPolicyExitOnFailure}},
				{"cache", types.RestartPolicyConfig{ExitOnEnd: true}},
			} {
				processes[svc.name] = types.ProcessConfig{
					Name:          svc.name,
					ReplicaName:   svc.name,
					Executable:    shell.ShellCommand,
					Args:          []string{shell.ShellArgument, getSleepCommand(60)},
					RestartPolicy: svc.policy,
				}
			}
			runner, err := NewProjectRunner(&ProjectOpts{
				project: &types.Project{ShellConfig: shell, Processes: processes},
			})
			if err != nil {
				t.Fatal(err)
			}

			done := make(chan error, 1)
			go func() { done <- runner.Run() }()
			var runErr error
			select {
			case runErr = <-done:
			case <-time.After(20 * time.Second):
				_ = runner.ShutDownProject()
				t.Fatal("project did not exit")
			}

			gotCode := 0
			var exitErr *ExitError
			if errors.As(runErr, &exitErr) {
				gotCode = exitErr.Code
			} else if runErr != nil {
				t.Fatalf("unexpected error: %v", runErr)
			}
			if gotCode != tt.wantCode {
				t.Errorf("project exit code = %d, want %d", gotCode, tt.wantCode)
			}
		})
	}
}

// A shutdown somebody asked for is not a failure, even though the processes it
// terminates exit non-zero and are configured to end the project when they do.
func TestRequestedShutdownExitsCleanly(t *testing.T) {
	shell := command.DefaultShellConfig()
	const name = "db"
	runner, err := NewProjectRunner(&ProjectOpts{
		project: &types.Project{
			ShellConfig: shell,
			Processes: map[string]types.ProcessConfig{
				name: {
					Name:          name,
					ReplicaName:   name,
					Executable:    shell.ShellCommand,
					Args:          []string{shell.ShellArgument, getSleepCommand(60)},
					RestartPolicy: types.RestartPolicyConfig{Restart: types.RestartPolicyExitOnFailure},
				},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan error, 1)
	go func() { done <- runner.Run() }()
	waitForProcessState(t, runner, name, types.ProcessStateRunning, 10*time.Second)

	if err := runner.ShutDownProject(); err != nil {
		t.Fatal(err)
	}
	select {
	case err := <-done:
		if err != nil {
			t.Errorf("project exited with %v after a requested shutdown, want a clean exit", err)
		}
	case <-time.After(20 * time.Second):
		t.Fatal("project did not exit")
	}
}

// A process killed by a signal reports 128+signal, as documented and as a shell
// would, instead of -1.
func TestSignalledProcessExitCode(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("relies on Unix signals")
	}
	shell := command.DefaultShellConfig()
	tests := []struct {
		name string
		cmd  string
		want int
	}{
		{name: "killed by SIGKILL", cmd: "kill -KILL $$", want: 128 + int(syscall.SIGKILL)},
		{name: "killed by SIGTERM", cmd: "kill -TERM $$", want: 128 + int(syscall.SIGTERM)},
		{name: "plain exit", cmd: "exit 7", want: 7},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			proc := NewProcess(
				withProcConf(&types.ProcessConfig{
					Name:        "p",
					ReplicaName: "p",
					Executable:  shell.ShellCommand,
					Args:        []string{shell.ShellArgument, tt.cmd},
				}),
				withLogger(pclog.NewNilLogger()),
				withProcState(&types.ProcessState{}),
				withProcLog(pclog.NewLogBuffer(10)),
			)
			if got := proc.run(); got != tt.want {
				t.Errorf("exit code = %d, want %d", got, tt.want)
			}
		})
	}
}

// Stopping a process with a shutdown timeout arms a SIGKILL for when the
// timeout expires. When the process is then restarted by its policy - a failed
// readiness probe is the case here - that SIGKILL belongs to the launch that
// was stopped, and must not land on its replacement.
func TestStopTimeoutDoesNotKillReplacement(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("relies on Unix signals")
	}
	launches := filepath.Join(t.TempDir(), "launches")
	proc := &types.ProcessConfig{
		Name:        "svc",
		ReplicaName: "svc",
		Command:     fmt.Sprintf("echo launched >> %q; exec sleep 60", launches),
		RestartPolicy: types.RestartPolicyConfig{
			Restart:        types.RestartPolicyAlways,
			BackoffSeconds: 1,
		},
		ShutDownParams: types.ShutDownParams{ShutDownTimeout: 2},
		// Fails for the first launch only.
		ReadinessProbe: &health.Probe{
			Exec: &health.ExecProbe{
				Command: fmt.Sprintf("test $(wc -l < %q) -ge 2", launches),
			},
			FailureThreshold: 1,
			PeriodSeconds:    1,
			InitialDelay:     1,
		},
	}
	proc.AssignProcessExecutableAndArgs(command.DefaultShellConfig(), "")

	p := NewProcess(
		withProcConf(proc),
		withLogger(pclog.NewNilLogger()),
		withProcState(&types.ProcessState{}),
		withProcLog(pclog.NewLogBuffer(100)),
	)
	finished := make(chan struct{})
	go func() {
		defer close(finished)
		_ = p.run()
	}()
	t.Cleanup(func() {
		_ = p.shutDownNoRestart()
		<-finished
	})

	if !waitForLineCount(t, launches, 2, 15*time.Second) {
		t.Fatalf("process was not restarted by its readiness probe; launches: %d", countLinesIn(t, launches))
	}
	// Well past the shutdown timeout of the launch that was stopped.
	time.Sleep(4 * time.Second)
	if got := countLinesIn(t, launches); got != 2 {
		t.Errorf("process was launched %d times, want 2: the replacement was killed", got)
	}
	if restarts := p.getState().Restarts; restarts != 1 {
		t.Errorf("restarts = %d, want 1", restarts)
	}
}

// Once a stop has been requested, the process must not be launched - however
// narrowly the request beat the launch.
func TestStartIsAbortedByAnEarlierStop(t *testing.T) {
	p := NewProcess(
		withProcConf(&types.ProcessConfig{Name: "p", ReplicaName: "p"}),
		withLogger(pclog.NewNilLogger()),
		withProcState(&types.ProcessState{Status: types.ProcessStatePending}),
		withProcLog(pclog.NewLogBuffer(10)),
	)
	p.runCancelFn()

	launched := false
	err := p.setStateAndRun(types.ProcessStateRunning, func() error {
		launched = true
		return nil
	})
	if !errors.Is(err, errStartAborted) {
		t.Errorf("err = %v, want %v", err, errStartAborted)
	}
	if launched {
		t.Error("the command was launched after the process had been stopped")
	}
	if status := p.getStatusName(); status != types.ProcessStatePending {
		t.Errorf("status = %s, want it left at %s", status, types.ProcessStatePending)
	}
}

// Stopping a process that has just ended must leave its final state alone.
func TestStopDoesNotOverwriteAFinalState(t *testing.T) {
	p := NewProcess(
		withProcConf(&types.ProcessConfig{Name: "p", ReplicaName: "p"}),
		withLogger(pclog.NewNilLogger()),
		withProcState(&types.ProcessState{Status: types.ProcessStateCompleted}),
		withProcLog(pclog.NewLogBuffer(10)),
	)
	if err := p.shutDownNoRestart(); err != nil {
		t.Fatal(err)
	}
	if status := p.getStatusName(); status != types.ProcessStateCompleted {
		t.Errorf("status = %s, want %s", status, types.ProcessStateCompleted)
	}
	if _, running := p.beginTerminating(); running {
		t.Error("a completed process was moved to Terminating")
	}
}

