func readEvents(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		t.Fatal(err)
	}
	return string(data)
}

// A restart must not launch the replacement while the old incarnation is still
// shutting down, or the two fight over whatever the old one has yet to release.
//
// The watch path is the one exercised: it skips backoff, so nothing but an
// explicit wait stands between the stop signal and the relaunch.
func TestRestartWaitsForOldIncarnationToExit(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("relies on Unix signals")
	}
	shell := command.DefaultShellConfig()
	const name = "api"

	tests := []struct {
		name string
		// cmd builds the process command from the server script.
		cmd func(script string) string
	}{
		{
			// The server is the command: its own exit is what has to be awaited.
			name: "server is the command",
			cmd:  func(script string) string { return "exec bash " + script },
		},
		{
			// The server runs under a shell that dies on SIGTERM at once and
			// leaves it behind, as `npm run`, a `cd x && server` one-liner or
			// any launcher script does. The command is gone long before the
			// server is; only its process group tells.
			name: "server is behind a wrapper",
			cmd:  func(script string) string { return "bash " + script + "; true" },
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			script, events := slowStopServer(t, t.TempDir())
			runner, err := NewProjectRunner(&ProjectOpts{
				project: &types.Project{
					ShellConfig: shell,
					Processes: map[string]types.ProcessConfig{
						name: {
							Name:        name,
							ReplicaName: name,
							Executable:  shell.ShellCommand,
							Args:        []string{shell.ShellArgument, tt.cmd(script)},
						},
					},
				},
			})
			if err != nil {
				t.Fatal(err)
			}
			go func() { _ = runner.Run() }()
			t.Cleanup(func() { _ = runner.ShutDownProject() })

			if !waitForLineCount(t, events, 1, 10*time.Second) {
				t.Fatalf("server never came up; events: %q", readEvents(t, events))
			}

			const restarts = 3
			for i := range restarts {
				if err := runner.RestartProcesses([]string{name}); err != nil {
					t.Fatalf("restart %d: %v", i+1, err)
				}
				if !waitForLineCount(t, events, i+2, 10*time.Second) {
					t.Fatalf("restart %d never brought the server back; events: %q", i+1, readEvents(t, events))
				}
			}

			got := readEvents(t, events)
			if strings.Contains(got, "CONFLICT") {
				t.Errorf("a replacement was launched while the old incarnation was still running; events: %q", got)
			}
			if ups := strings.Count(got, "up\n"); ups != restarts+1 {
				t.Errorf("server came up %d times, want %d; events: %q", ups, restarts+1, got)
			}
		})
	}
}

// A restart that is waiting for a process to stop must give up when the project
// shuts down, rather than hold the shutdown hostage - and must not launch
