// A command that exits is done, even if something it started still holds its
// output open. The exit must not be missed, and what depends on it must start.
func TestProcessCompletesWhileItsOutputIsHeldOpen(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("relies on Unix process semantics")
	}
	shell := command.DefaultShellConfig()
	const (
		migrate = "migrate"
		api     = "api"
	)
	runner, err := NewProjectRunner(&ProjectOpts{
		project: &types.Project{
			ShellConfig: shell,
			LogLength:   100,
			Processes: map[string]types.ProcessConfig{
				migrate: {
					Name:        migrate,
					ReplicaName: migrate,
					Executable:  shell.ShellCommand,
					// The helper inherits stdout and stderr and outlives the
					// migration by far.
					Args: []string{shell.ShellArgument, "echo migrating; sleep 60 & echo migrated"},
				},
				api: {
					Name:        api,
					ReplicaName: api,
					Executable:  shell.ShellCommand,
					Args:        []string{shell.ShellArgument, getSleepCommand(60)},
					DependsOn: types.DependsOnConfig{
						migrate: {Condition: types.ProcessConditionCompletedSuccessfully},
					},
				},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	go func() { _ = runner.Run() }()
	t.Cleanup(func() { _ = runner.ShutDownProject() })

	waitForProcessLaunched(t, runner, migrate, 10*time.Second)
	proc := runner.getRunningProcess(migrate)
	if proc != nil {
		// The helper is not ours to stop; reap it by hand once the test is over.
		t.Cleanup(func() { _ = syscall.Kill(-proc.getState().Pid, syscall.SIGKILL) })
	}

	waitForProcessState(t, runner, migrate, types.ProcessStateCompleted, 10*time.Second)
	waitForProcessState(t, runner, api, types.ProcessStateRunning, 10*time.Second)

	state, err := runner.GetProcessState(migrate)
	if err != nil {
		t.Fatal(err)
	}
