p='src/pclog/logger_facade.go'
s=open(p).read()
def rep(old,new):
    global s
    assert s.count(old)==1, old[:60]
    s=s.replace(old,new)
rep('''	closer        sync.Once
	isClosed      atomic.Bool
''','''	closer        sync.Once
	isClosed      atomic.Bool
	// sendMtx makes "check isClosed, then send" one step with respect to
	// Close. Senders share it; Close takes it exclusively before closing the
	// channel, so a line arriving as the log is closed is dropped rather than
	// sent on a closed channel.
	sendMtx       sync.RWMutex
''')
rep('''func (l *PCLog) Info(message string, process string, replica int) {
	if l.isClosed.Load() {
		return
	}
	l.logEventChan <- logEvent{
		message: message,
		process: process,
		replica: replica,
		isErr:   false,
	}
}

func (l *PCLog) Error(message string, process string, replica int) {
	if l.isClosed.Load() {
		return
	}
	l.logEventChan <- logEvent{
		message: message,
		process: process,
		replica: replica,
		isErr:   true,
	}
}
''','''func (l *PCLog) Info(message string, process string, replica int) {
	l.send(logEvent{
		message: message,
		process: process,
		replica: replica,
		isErr:   false,
	})
}

func (l *PCLog) Error(message string, process string, replica int) {
	l.send(logEvent{
		message: message,
		process: process,
		replica: replica,
		isErr:   true,
	})
}

// send queues an event unless the log has been closed.
//
// A process's output can keep arriving after the process has ended and its log
// was closed - something it left running may still hold its stdout - so a
// writer racing with Close is an ordinary occurrence, not a programming error.
// The collector keeps draining the channel independently of sendMtx, so a
// sender blocked on a full channel never keeps Close waiting for long.
func (l *PCLog) send(event logEvent) {
	l.sendMtx.RLock()
	defer l.sendMtx.RUnlock()
	if l.isClosed.Load() {
		return
	}
	l.logEventChan <- event
}
''')
rep('''	l.closer.Do(func() {
		l.isClosed.Store(true)
		close(l.logEventChan)
		l.wg.Wait()
''','''	l.closer.Do(func() {
		l.sendMtx.Lock()
		l.isClosed.Store(true)
		close(l.logEventChan)
		l.sendMtx.Unlock()
		l.wg.Wait()
''')
open(p,'w').write(s)
EOF
gofmt -w src/pclog/logger_facade.go && cat > src/pclog/logger_facade_test.go <<'EOF'
package pclog

import (
	"path/filepath"
	"sync"
	"testing"
)

// Lines can still arrive while - and after - the log is being closed: the
// output of a process is read independently of the process ending. Closing must
// drop them, not panic on a closed channel.
func TestLoggerCloseWhileWriting(t *testing.T) {
	for i := range 200 {
		logger := NewLogger()
		logger.Open(filepath.Join(t.TempDir(), "proc.log"), nil)

		var writers sync.WaitGroup
		start := make(chan struct{})
		for w := range 4 {
			writers.Add(1)
			go func() {
				defer writers.Done()
				<-start
				for range 50 {
					if w%2 == 0 {
						logger.Info("line", "proc", 0)
					} else {
						logger.Error("line", "proc", 0)
					}
				}
			}()
		}
		close(start)
		logger.Close()
		writers.Wait()

		// Closed for good: later writes are no-ops as well.
		logger.Info("after close", "proc", 0)
		if t.Failed() {
			t.Fatalf("iteration %d", i)
		}
	}
}
EOF
