// signalTree signals the command and those of its descendants that share our
// process group, without touching anything else in that group.
//
// The descendants are remembered. Once the command has exited they are
// reparented and can no longer be found by walking down from it, yet they are
// what a later SIGKILL is meant for, and what WaitGroupExit has to wait on.
func (c *CmdWrapper) signalTree(sig syscall.Signal) error {
	own := syscall.Getpgrp()
	c.treeMtx.Lock()
	for _, pid := range liveDescendants(c.Pid()) {
		if !slices.Contains(c.treePids, pid) {
			c.treePids = append(c.treePids, pid)
		}
	}
	targets := make([]int, 0, len(c.treePids))
	for _, pid := range c.treePids {
		// A process that left our group has detached itself from the command,
		// and a PID that is no longer in it at all may have been recycled.
		if pgid, err := syscall.Getpgid(pid); err == nil && pgid == own && isPidRunning(pid) {
			targets = append(targets, pid)
		}
