	c.treePids = targets
	c.treeMtx.Unlock()

	signalled := false
	err := c.cmd.Process.Signal(sig)
	switch {
	case err == nil:
		signalled = true
	case !errors.Is(err, os.ErrProcessDone):
		return err
	}
	for _, pid := range targets {
		if syscall.Kill(pid, sig) == nil {
			signalled = true
		}
	}
	if !signalled {
		return syscall.ESRCH
	}
	return nil
}

// isPidRunning reports whether pid is a running process, as opposed to one that
// is gone or has exited without being reaped yet.
func isPidRunning(pid int) bool {
	if errors.Is(syscall.Kill(pid, 0), syscall.ESRCH) {
		return false
	}
	return !isZombie(pid)
}

// hasRunningTree reports whether any of the descendants signalled by signalTree
// is still running.
func (c *CmdWrapper) hasRunningTree() bool {
	c.treeMtx.Lock()
	defer c.treeMtx.Unlock()
	return slices.ContainsFunc(c.treePids, isPidRunning)
}
