''','''// shutdownSignals are the signals on which process-compose shuts its processes
// down before exiting.
//
// SIGQUIT (Ctrl-\\) is among them on purpose. Left alone, the Go runtime answers
// it by dumping every goroutine and exiting on the spot - and the processes,
// each in a process group of its own and so untouched by a signal from the
// terminal, are left running with nobody to stop them.
var shutdownSignals = []os.Signal{syscall.SIGTERM, os.Interrupt, syscall.SIGHUP, syscall.SIGQUIT}

// forceSignalGap is how long after the first signal a further one is taken for
// part of the same request rather than for a demand to hurry up. Supervisors
// and closing terminals routinely deliver two signals at once (SIGTERM with
// SIGHUP, say), and that must not turn a graceful shutdown into a kill.
const forceSignalGap = time.Second

func setSignal(shutDown func(), forceShutDown func(sig os.Signal)) {
	cancelChan := make(chan os.Signal, 4)
	signal.Notify(cancelChan, shutdownSignals...)
	go handleSignals(cancelChan, shutDown, forceShutDown, forceSignalGap)
}

// handleSignals shuts the project down on the first signal, and forces the
// matter on a later one.
//
// A graceful shutdown waits for every process to exit, and a process that
// ignores its stop signal and has no shutdown timeout never does. Without a way
// to insist, the only way out of that is to kill process-compose itself, which
// leaves all of its processes behind.
func handleSignals(signals <-chan os.Signal, shutDown func(), forceShutDown func(sig os.Signal), gap time.Duration) {
	sig := <-signals
	log.Info().Msgf("Caught %v - Shutting down the running processes...", sig)
	started := time.Now()
	go shutDown()
	for sig = range signals {
		if time.Since(started) < gap {
			log.Debug().Msgf("Caught %v right after the shutdown began - ignoring", sig)
			continue
		}
		log.Warn().Msgf("Caught %v during the shutdown - killing the running processes", sig)
		forceShutDown(sig)
		return
	}
}

