// shell's own convention for a program ended by that signal.
func signalExitCode(sig os.Signal) int {
	if number, ok := sig.(syscall.Signal); ok {
		return 128 + int(number)
	}
	return 1
}

func runHeadless(project *app.ProjectRunner) error {
	util.SetProjectNameAsTerminalTitle(project)
	setSignal(
		func() {
			fmt.Fprintln(os.Stderr, "Shutting down the running processes... (signal again to kill them)")
			_ = project.ShutDownProject()
		},
		func(sig os.Signal) {
			fmt.Fprintln(os.Stderr, "Killing the running processes...")
			project.ForceShutDownProject(signalExitCode(sig))
		},
	)
	return project.Run()
}
